/// Grace period, in seconds, during which a rotated token's old secret
/// keeps validating after its `revoked_at` stamp (RFC-0004 fixes the
/// `aos-server` bug where this window was recorded but not honored).
const ROTATION_GRACE_SECS: i64 = 3600;

/// Maximum `audit_log` rows scanned per [`Database::list_audit`] call.
///
/// The audit log is append-only and unbounded, so the query reads at most this
/// many most-recent rows (`ORDER BY id DESC LIMIT`) before scope-filtering them
/// in Rust — a single request can never materialize the whole table. Generous
/// enough that a paged console/RPC view always sees recent activity.
const MAX_AUDIT_SCAN: i64 = 10_000;

/// Largest integer that every Hub SQL transport represents exactly.
///
/// Native drivers preserve the full SQLite/PostgreSQL/MySQL `i64` range, but
/// Durable Object SQL crosses the JavaScript number boundary. Relational ids
/// generated by shared core must therefore remain in the positive exact
/// integer range common to every runtime.
const PORTABLE_RELATIONAL_ID_MAX: i64 = 9_007_199_254_740_991;

/// Derives a positive, cross-runtime relational key from a stable incarnation.
fn portable_relational_id(incarnation: uuid::Uuid) -> i64 {
    (incarnation.as_u128() % PORTABLE_RELATIONAL_ID_MAX as u128) as i64 + 1
}

/// Ordered schema migrations; index = version - 1.
/// Squashed fresh-install schema for the final Hub topology.
///
/// Upgrade/cutover is deliberately an offline artifact. The first migration
/// establishes the topology hard-cutover schema; subsequent entries are
/// forward-only additions shared by native SQLite and Cloudflare D1.
pub const MIGRATIONS: &[&str] = &[include_str!("schema.sql"), include_str!("auth_refresh.sql")];

/// Identity stamped into databases created by the topology hard-cutover
/// schema. Unlike the historical integer version, this value cannot collide
/// with a pre-cutover deployment whose independent migration history happened
/// to have the same length.
pub const SCHEMA_IDENTITY: &str = "aos-hub/topology-hard-cutover/1";

/// Returns every migration's individual SQL statements, in order.
///
/// Splits the [`MIGRATIONS`] scripts at statement boundaries via
/// [`split_statements`](crate::backend::split_statements), flattened across all
/// versions. Useful for tooling that must apply the schema outside the
/// [`Database`] migration path — e.g. seeding a test HubDb over its binding, or the
/// `aos-hub schema dump` command.
#[must_use]
pub fn migration_statements() -> Vec<String> {
    MIGRATIONS
        .iter()
        .flat_map(|m| crate::backend::split_statements(m))
        .collect()
}

/// Marker error: a membership mutation was refused because it would leave an
/// org with zero owners.
///
/// Raised when the write-time guard in [`Database::revoke_membership_owner_safe`]
/// or [`Database::set_membership_role_owner_safe`] refuses the mutation, so a
/// caller can classify the failure through `anyhow` context chains via
/// [`is_last_owner_error`] and surface it as a `409 Conflict` rather than a
/// generic `500`.
#[derive(Debug, thiserror::Error)]
#[error("refusing to leave org scope '{0}' without an owner")]
pub struct LastOwnerError(pub String);

/// Whether any error in `err`'s chain is a [`LastOwnerError`].
///
/// Walks the full `anyhow` context chain, so classification survives any
/// number of `.context(…)` layers added by callers.
#[must_use]
pub fn is_last_owner_error(err: &anyhow::Error) -> bool {
    err.chain()
        .any(|cause| cause.downcast_ref::<LastOwnerError>().is_some())
}

/// A registered registry (system-of-record row).
#[derive(Debug, Clone)]
pub struct RegistryRecord {
    /// Database id.
    pub id: i64,
    /// Immutable non-reusable registry identity.
    pub stable_id: String,
    /// Exact registry authorization scope.
    pub scope_key: String,
    /// Infrastructure-owner scope used by placements and delivery grants.
    pub owner_scope_key: String,
    /// URL path slug the registry is served under.
    ///
    /// For phase-1 unowned registries this is a flat slug (`"cdn"`); for
    /// phase-2 managed registries it is the full canonical path
    /// (`"acme/infra/prod/cdn"`) — see the [module docs](self).
    pub slug: String,
    /// Pinned trust anchors in `name:Ed25519:<base64>` form.
    pub trust_keys: Vec<String>,
    /// Whether indexing fails closed on missing/invalid signatures.
    pub require_signatures: bool,
    /// Owning org id, or `None` for an instance-level unowned registry.
    pub org_id: Option<i64>,
    /// Owning project's materialized path (`""` for an org-root registry).
    pub project_path: String,
    /// Visibility: `public`, `internal`, or `private`.
    pub visibility: String,
    /// Crawl posture for the generated `robots.txt`: one of `allow_all`,
    /// `allow_no_ai`, or `deny_all` (see [`crate::crawl::CrawlPolicy`]).
    pub crawl_policy: String,
    /// Operator-authored `llms.txt` body served verbatim, or `None` to serve
    /// the document generated from the registry's packages and channels.
    pub llms_txt_body: Option<String>,
    /// Optimistic concurrency version for registry configuration.
    pub resource_version: i64,
    /// Last configuration update time in Unix seconds.
    pub updated_at: i64,
}

/// A storage binding (system-of-record row): a named backend an org's
/// surfaces use through explicit physical placements.
#[derive(Debug, Clone, Default)]
pub struct StorageBindingRecord {
    /// Database id.
    pub id: i64,
    /// Owning org id, or `None` for the instance-level default binding
    /// ([`is_instance_default`](Self::is_instance_default)).
    pub org_id: Option<i64>,
    /// Binding name, unique within the org.
    pub name: String,
    /// Backend kind: `local_fs` (a native host directory), `s3`/`r2` (an
    /// externally configured S3-compatible store), or the instance-owned
    /// Worker `deployment_r2` singleton. Organization rows only use `s3`/`r2`.
    pub kind: String,
    /// Whether this is the singleton instance-level default storage binding.
    /// Exactly one row carries this; it has a `None` `org_id`.
    pub is_instance_default: bool,
    /// Stable API identity, independent of database ids and display names.
    pub stable_id: String,
    /// Canonical owner scope (`instance` or `org:<id>`).
    pub owner_scope_key: String,
    /// Canonical local-filesystem root for a local binding.
    pub local_root_path: Option<String>,
    /// Object-store bucket for an S3-compatible binding.
    pub object_bucket: Option<String>,
    /// Binding-owned prefix within the object-store bucket.
    pub object_prefix: Option<String>,
    /// Canonical endpoint scheme.
    pub endpoint_scheme: Option<String>,
    /// Endpoint host representation (`dns`, `ipv4`, or `ipv6`).
    pub endpoint_host_kind: Option<String>,
    /// Canonical endpoint host bytes.
    pub endpoint_host_bytes: Option<Vec<u8>>,
    /// Explicit endpoint port.
    pub endpoint_port: Option<i64>,
    /// Object-store request-signing region.
    pub signing_region: Option<String>,
    /// Canonical access mode for the binding.
    pub access_mode: Option<String>,
    /// Optimistic-concurrency version.
    pub resource_version: i64,
    /// Unix time the binding was created.
    pub created_at: i64,
    /// Unix time the desired binding spec last changed.
    pub updated_at: i64,
}

/// A storage-binding row safe to expose to principals with read-only access.
///
/// This projection deliberately cannot represent provider coordinates,
/// credentials, or credential-version references. Queries returning it select
/// only these columns at the SQL boundary.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageBindingReadDetail {
    /// Database identity used only for same-request joins.
    pub id: i64,
    /// Owning organization, or `None` for the instance default.
    pub org_id: Option<i64>,
    /// Human-readable binding name.
    pub name: String,
    /// Provider kind without its connection coordinates.
    pub kind: String,
    /// Whether this is the deployment-provisioned singleton.
    pub is_instance_default: bool,
    /// Stable API identity.
    pub stable_id: String,
    /// Canonical owner authorization scope.
    pub owner_scope_key: String,
    /// Optimistic concurrency version.
    pub resource_version: i64,
    /// Creation time in Unix seconds.
    pub created_at: i64,
    /// Last desired-spec update time in Unix seconds.
    pub updated_at: i64,
}

/// A compact storage-binding identity safe for read-only inventory pages.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageBindingReadSummary {
    /// Database identity used only for same-request joins.
    pub id: i64,
    /// Owning organization, or `None` for the instance default.
    pub org_id: Option<i64>,
    /// Human-readable binding name.
    pub name: String,
    /// Provider kind without its connection coordinates.
    pub kind: String,
    /// Whether this is the deployment-provisioned singleton.
    pub is_instance_default: bool,
    /// Stable API identity.
    pub stable_id: String,
}

impl From<&StorageBindingRecord> for StorageBindingReadSummary {
    fn from(binding: &StorageBindingRecord) -> Self {
        Self {
            id: binding.id,
            org_id: binding.org_id,
            name: binding.name.clone(),
            kind: binding.kind.clone(),
            is_instance_default: binding.is_instance_default,
            stable_id: binding.stable_id.clone(),
        }
    }
}

const STORAGE_BINDING_READ_DETAIL_SQL: &str =
    "SELECT id, org_id, name, kind, is_instance_default, stable_id, owner_scope_key, \
     resource_version, created_at, updated_at \
     FROM storage_bindings WHERE stable_id = ?1";

const STORAGE_BINDING_READ_SUMMARY_SQL: &str =
    "SELECT id, org_id, name, kind, is_instance_default, stable_id \
     FROM storage_bindings WHERE org_id = ?1 ORDER BY name";

/// One immutable credential-version reference attached to a storage binding.
