    /// Resolves one live operation-inventory target to its authorization scope.
    ///
    /// Resolution uses the target's system-of-record table, never operation
    /// history, so callers can authorize before querying whether operations
    /// exist for the target.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown target kind, malformed target identity,
    /// or database failure.
    pub async fn topology_operation_target_scope(
        &self,
        target_kind: &str,
        stable_id: &str,
    ) -> Result<Option<String>> {
        validate_key_bytes(stable_id, "operation target stable id", 255)?;
        if target_kind == "placement" {
            let (surface, name) = stable_id
                .rsplit_once("/placement:")
                .context("malformed placement operation target")?;
            let (surface_kind, _) = surface
                .split_once(':')
                .context("malformed placement operation surface")?;
            let (join, predicate) = match surface_kind {
                "registry" => (
                    "JOIN registries s ON s.id = p.registry_id",
                    "s.stable_id = ?1",
                ),
                "cache" => (
                    "JOIN binary_caches s ON s.id = p.cache_id",
                    "s.stable_id = ?1",
                ),
                _ => bail!("unknown placement operation surface kind"),
            };
            return self
                .backend
                .query_opt(
                    &format!(
                        "SELECT s.scope_key
                           FROM surface_placements p {join}
                          WHERE {predicate} AND p.name = ?2"
                    ),
                    &vals![surface, name],
                )
                .await?
                .map(|row| row.get(0))
                .transpose();
        }
        let sql = match target_kind {
            "registry" => "SELECT scope_key FROM registries WHERE stable_id = ?1",
            "binary_cache" => "SELECT scope_key FROM binary_caches WHERE stable_id = ?1",
            "domain" => "SELECT owner_scope_key FROM domains WHERE stable_id = ?1",
            "network_boundary" => "SELECT owner_scope_key FROM network_boundaries WHERE id = ?1",
            "delivery_endpoint" => "SELECT owner_scope_key FROM delivery_endpoints WHERE id = ?1",
            "storage_gateway" => "SELECT owner_scope_key FROM storage_gateways WHERE id = ?1",
            "storage_binding" => {
                "SELECT owner_scope_key FROM storage_bindings WHERE stable_id = ?1"
            }
            "delivery_route" => {
                "SELECT endpoint.owner_scope_key FROM delivery_routes route
                   JOIN delivery_endpoints endpoint ON endpoint.id = route.endpoint_id
                  WHERE route.id = ?1"
            }
            "placement_policy" => {
                "SELECT COALESCE(registry.scope_key, cache.scope_key)
                   FROM placement_policies policy
                   LEFT JOIN registries registry ON registry.id = policy.registry_id
                   LEFT JOIN binary_caches cache ON cache.id = policy.cache_id
                  WHERE policy.id = ?1"
            }
            "retention_subscription" => {
                return self
                    .numeric_operation_target_scope("cache_retention_subscriptions", stable_id)
                    .await
            }
            "population_target" => {
                return self
                    .numeric_operation_target_scope("cache_population_targets", stable_id)
                    .await
            }
            "cache_gc_generation" => {
                "SELECT cache.scope_key
                   FROM cache_gc_generations generation
                   JOIN binary_caches cache ON cache.id = generation.cache_id
                  WHERE generation.generation_id = ?1"
            }
            other => bail!("unknown operation target kind '{other}'"),
        };
        self.backend
            .query_opt(sql, &vals![stable_id])
            .await?
            .map(|row| row.get(0))
            .transpose()
    }

    async fn numeric_operation_target_scope(
        &self,
        table: &str,
        stable_id: &str,
    ) -> Result<Option<String>> {
        let id = stable_id
            .parse::<i64>()
            .context("numeric operation target has a malformed identity")?;
        self.backend
            .query_opt(
                &format!(
                    "SELECT cache.scope_key FROM {table} target
                     JOIN binary_caches cache ON cache.id = target.cache_id
                     WHERE target.id = ?1"
                ),
                &vals![id],
            )
            .await?
            .map(|row| row.get(0))
            .transpose()
    }

    /// Lists operations for a surface using a stable newest-first keyset.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_topology_operations_page(
        &self,
        target_kind: &str,
        stable_id: &str,
        state: Option<&str>,
        page_size: u32,
        after_operation_id: Option<&str>,
    ) -> Result<TopologyOperationPage> {
        let state = state.unwrap_or("");
        if !state.is_empty()
            && !matches!(
                state,
                "pending" | "running" | "succeeded" | "failed" | "cancelled"
            )
        {
            bail!("invalid operation state filter '{state}'");
        }
        let after_created_at = if let Some(cursor) = after_operation_id {
            validate_key_bytes(cursor, "operation page token", 64)?;
            Some(
                self.backend
                    .query_opt(
                        "SELECT o.created_at FROM topology_operations o
                          WHERE o.operation_id = ?1 AND o.primary_target_kind = ?2
                            AND o.primary_target_stable_id = ?3
                            AND (?4 = '' OR o.state = ?4)",
                        &vals![cursor, target_kind, stable_id, state],
                    )
                    .await?
                    .context("operation page token does not belong to this inventory")?
                    .get::<i64>(0)?,
            )
        } else {
            None
        };
        let limit = if page_size == 0 {
            100_i64
        } else {
            i64::from(page_size.min(500))
        };
        let rows = self
            .backend
            .query(
                &format!(
                    "SELECT {OPERATION_COLUMNS} FROM topology_operations o
                      WHERE o.primary_target_kind = ?1 AND o.primary_target_stable_id = ?2
                        AND (?3 = '' OR o.state = ?3)
                        AND (?4 IS NULL OR o.created_at < ?4
                          OR (o.created_at = ?4 AND o.operation_id > ?5))
                      ORDER BY o.created_at DESC, o.operation_id
                      LIMIT ?6"
                ),
                &vals![
                    target_kind,
                    stable_id,
                    state,
                    after_created_at,
                    after_operation_id,
                    limit + 1
                ],
            )
            .await?;
        let mut records = rows
            .iter()
            .map(row_to_topology_operation)
            .collect::<Result<Vec<_>>>()?;
        let next_cursor = if records.len() > limit as usize {
            records.pop();
            records.last().map(|record| record.operation_id.clone())
        } else {
            None
        };
        Ok(TopologyOperationPage {
            records,
            next_cursor,
        })
    }

    /// Lists every operation for an internal controller projection.
    ///
    /// User-facing inventory must use [`Database::list_topology_operations_page`].
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_topology_operations(
        &self,
        target_kind: &str,
        stable_id: &str,
    ) -> Result<Vec<TopologyOperationRecord>> {
        self.backend
            .query(
                &format!(
                    "SELECT {OPERATION_COLUMNS} FROM topology_operations o
                      WHERE o.primary_target_kind = ?1 AND o.primary_target_stable_id = ?2
                      ORDER BY o.created_at DESC, o.operation_id"
                ),
                &vals![target_kind, stable_id],
            )
            .await?
            .iter()
            .map(row_to_topology_operation)
            .collect()
    }

    /// Lists pending/running operations whose immutable targets touch a surface.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure or malformed target data.
    pub async fn list_active_surface_operations(
        &self,
        surface: SurfaceTarget,
    ) -> Result<Vec<TopologyOperationRecord>> {
        let mut targets = std::collections::BTreeSet::new();
        match surface {
            SurfaceTarget::Registry(id) => {
                let registry = self
                    .registry_by_id(id)
                    .await?
                    .context("registry surface does not exist")?;
                targets.insert(("registry".to_string(), registry.stable_id));
            }
            SurfaceTarget::BinaryCache(id) => {
                let cache = self
                    .binary_cache_by_id(id)
                    .await?
                    .context("binary-cache surface does not exist")?;
                targets.insert(("binary_cache".to_string(), cache.stable_id));
            }
        }
        for placement in self.list_surface_placements(surface).await? {
            targets.insert((
                "placement".to_string(),
                self.surface_placement_operation_target_id(placement.id)
                    .await?,
            ));
        }
        let mut selected = Vec::new();
        let active_operations = self
            .backend
            .query(
                &format!(
                    "SELECT {OPERATION_COLUMNS} FROM topology_operations o
                     WHERE o.state IN ('pending', 'running')
                     ORDER BY o.created_at DESC, o.operation_id"
                ),
                &[],
            )
            .await?
            .iter()
            .map(row_to_topology_operation)
            .collect::<Result<Vec<_>>>()?;
        for operation in active_operations {
            if !matches!(operation.state.as_str(), "pending" | "running") {
                continue;
            }
            if targets.contains(&(
                operation.primary_target_kind.clone(),
                operation.primary_target_stable_id.clone(),
            )) || self
                .topology_operation_targets(&operation.operation_id)
                .await?
                .iter()
                .any(|target| {
                    targets.contains(&(target.target_kind.clone(), target.stable_id.clone()))
                })
            {
                selected.push(operation);
            }
        }
        Ok(selected)
    }

    /// Lists the immutable target snapshot for an operation.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn topology_operation_targets(
        &self,
        operation_id: &str,
    ) -> Result<Vec<TopologyOperationTargetRecord>> {
        let Some(operation) = self.topology_operation(operation_id).await? else {
            return Ok(Vec::new());
        };
        let mut targets = vec![TopologyOperationTargetRecord {
            operation_id: operation.operation_id.clone(),
            role: "primary".to_string(),
            target_kind: operation.primary_target_kind,
            stable_id: operation.primary_target_stable_id,
            authorization_scope_key: operation.authorization_scope_key,
            control_permission: crate::auth::permission_from_str(&operation.control_permission)
                .context("operation has an invalid primary control permission")?,
            generation_key: operation.primary_target_generation_key,
            configuration_digest: operation.primary_target_configuration_digest,
        }];
        let mut secondary = self
            .backend
            .query(
                "SELECT operation_id, role, target_kind, stable_id, authorization_scope_key,
             control_permission, generation_key, configuration_digest
             FROM operation_secondary_targets WHERE operation_id = ?1
             ORDER BY role, target_kind, stable_id, generation_key",
                &vals![operation_id],
            )
            .await?
            .iter()
            .map(|row| {
                Ok(TopologyOperationTargetRecord {
                    operation_id: row.get(0)?,
                    role: row.get(1)?,
                    target_kind: row.get(2)?,
                    stable_id: row.get(3)?,
                    authorization_scope_key: row.get(4)?,
                    control_permission: crate::auth::permission_from_str(&row.get::<String>(5)?)
                        .context("operation has an invalid secondary control permission")?,
                    generation_key: row.get(6)?,
                    configuration_digest: row.get(7)?,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        targets.append(&mut secondary);
        Ok(targets)
    }

    /// Claims a pending or stale-running domain probe under operation CAS.
    ///
    /// A running claim becomes stealable after `lease_seconds`, allowing a
    /// request terminated during external I/O to be retried without leaving the
    /// operation permanently stuck. A fresh running claim is left untouched.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid lease, database failure, or malformed
    /// operation state.
    pub async fn claim_domain_probe_operation(
        &self,
        operation_id: &str,
        expected_version: i64,
        lease_seconds: i64,
    ) -> Result<Option<TopologyOperationRecord>> {
        if lease_seconds <= 0 {
            bail!("domain probe claim lease must be positive");
        }
        let now = unix_now();
        let changed = self
            .backend
            .execute(
                "UPDATE topology_operations SET state = 'running', started_at = ?3,
               finished_at = NULL, error = NULL, resource_version = resource_version + 1
             WHERE operation_id = ?1 AND operation_kind = 'domain_probe'
               AND resource_version = ?2
               AND (state = 'pending' OR (state = 'running' AND started_at <= ?4))",
                &vals![operation_id, expected_version, now, now - lease_seconds],
            )
            .await?;
        if changed == 0 {
            return Ok(None);
        }
        self.topology_operation(operation_id).await
    }

