    /// Counts still-live pin identities sealed into a coordination operation.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn count_live_network_boundary_pins(&self, pin_ids: &[String]) -> Result<i64> {
        let mut live = 0_i64;
        for pin_id in pin_ids {
            if self
                .backend
                .query_opt(
                    "SELECT 1 FROM network_boundary_serving_pins WHERE pin_id = ?1",
                    &vals![pin_id],
                )
                .await?
                .is_some()
            {
                live += 1;
            }
        }
        Ok(live)
    }

    /// Advances an operation with optimistic concurrency.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid state, malformed detail, a stale
    /// version, missing operation, or database failure.
    #[allow(clippy::too_many_arguments)]
    pub async fn update_topology_operation(
        &self,
        operation_id: &str,
        expected_version: i64,
        state: &str,
        progress_current: i64,
        progress_total: Option<i64>,
        detail_json: &str,
        error: Option<&str>,
        started_at: Option<i64>,
        finished_at: Option<i64>,
    ) -> Result<TopologyOperationRecord> {
        if !matches!(state, "running" | "succeeded" | "failed" | "cancelled") {
            bail!("invalid topology-operation state '{state}'");
        }
        validate_json_value(detail_json, "operation detail")?;
        if progress_current < 0 || progress_total.is_some_and(|total| total < progress_current) {
            bail!("operation progress must be non-negative and cannot exceed its total");
        }
        match state {
            "running" if started_at.is_none() || finished_at.is_some() || error.is_some() => {
                bail!("a running operation requires started_at and no finish/error")
            }
            "succeeded" if started_at.is_none() || finished_at.is_none() || error.is_some() => {
                bail!("a succeeded operation requires start/finish times and no error")
            }
            "failed" if started_at.is_none() || finished_at.is_none() || error.is_none() => {
                bail!("a failed operation requires start/finish times and an error")
            }
            "cancelled" if started_at.is_none() || finished_at.is_none() => {
                bail!("a cancelled operation requires start/finish times")
            }
            _ => {}
        }
        if finished_at
            .zip(started_at)
            .is_some_and(|(finish, start)| finish < start)
        {
            bail!("operation finish time cannot precede its start time");
        }
        let affected = self
            .backend
            .execute(
                "UPDATE topology_operations SET state = ?3, progress_current = ?4,
                progress_total = COALESCE(?5, progress_total), detail_json = ?6, error = ?7,
                started_at = ?8, finished_at = ?9,
                resource_version = resource_version + 1
             WHERE operation_id = ?1 AND resource_version = ?2
               AND progress_current <= ?4
               AND (progress_total IS NULL OR ?5 IS NULL OR progress_total = ?5)
               AND (?3 <> 'succeeded' OR COALESCE(?5, progress_total) IS NULL
                    OR ?4 = COALESCE(?5, progress_total))
               AND ((state = 'pending' AND ?3 IN ('running', 'cancelled'))
                 OR (state = 'running' AND ?3 IN ('succeeded', 'failed', 'cancelled'))) ",
                &vals![
                    operation_id,
                    expected_version,
                    state,
                    progress_current,
                    progress_total,
                    detail_json,
                    error,
                    started_at,
                    finished_at
                ],
            )
            .await?;
        if affected != 1 {
            bail!("topology operation is missing or its resource version is stale");
        }
        self.topology_operation(operation_id)
            .await?
            .context("updated topology operation disappeared")
    }

    /// Applies an idempotent caller-requested operation transition.
    ///
    /// The mutation key is persisted in the same transaction as the state CAS.
    /// Replaying the same request returns the recorded result; reusing a key for
    /// another mutation or expected version is rejected.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid key, mutation, state transition, stale
    /// resource version, conflicting replay, or database failure.
    pub async fn mutate_topology_operation(
        &self,
        operation_id: &str,
        expected_version: i64,
        mutation_kind: &str,
        idempotency_key: &str,
    ) -> Result<TopologyOperationRecord> {
        validate_key_bytes(idempotency_key, "operation mutation idempotency key", 128)?;
        let (from_states, next_state, finished_at) = match mutation_kind {
            "cancel" => ("'pending', 'running'", "cancelled", Some(unix_now())),
            // A retry is re-queued rather than marked running. Only a controller
            // claim may establish the running lease and its fencing version.
            "retry" => ("'failed', 'cancelled'", "pending", None),
            other => bail!("invalid topology-operation mutation '{other}'"),
        };
        if expected_version <= 0 {
            bail!("operation resource version must be positive");
        }
        if let Some(row) = self
            .backend
            .query_opt(
                "SELECT mutation_kind, expected_resource_version,
                        resulting_resource_version
                   FROM topology_operation_mutations
                  WHERE operation_id = ?1 AND idempotency_key = ?2",
                &vals![operation_id, idempotency_key],
            )
            .await?
        {
            let recorded_kind: String = row.get(0)?;
            let recorded_expected: i64 = row.get(1)?;
            let resulting_version: i64 = row.get(2)?;
            if recorded_kind != mutation_kind || recorded_expected != expected_version {
                bail!("operation idempotency key was used for another mutation");
            }
            let operation = self
                .topology_operation(operation_id)
                .await?
                .context("mutated topology operation disappeared")?;
            if operation.resource_version < resulting_version {
                bail!("operation mutation result is not yet visible");
            }
            return Ok(operation);
        }

        let now = unix_now();
        let transition = format!(
            "UPDATE topology_operations
                SET state = ?3,
                    started_at = CASE WHEN ?3 = 'pending' THEN NULL ELSE COALESCE(started_at, ?4) END,
                    finished_at = ?5,
                    error = CASE WHEN ?3 = 'pending' THEN NULL ELSE error END,
                    progress_current = CASE WHEN ?3 = 'pending' THEN 0 ELSE progress_current END,
                    resource_version = resource_version + 1
              WHERE operation_id = ?1 AND resource_version = ?2
                AND state IN ({from_states})"
        );
        let result = self
            .backend
            .checked_batch(&[
                Statement::new(
                    transition,
                    vals![operation_id, expected_version, next_state, now, finished_at],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO topology_operation_mutations
                     (operation_id, idempotency_key, mutation_kind,
                      expected_resource_version, resulting_resource_version, created_at)
                     VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
                    vals![
                        operation_id,
                        idempotency_key,
                        mutation_kind,
                        expected_version,
                        expected_version + 1,
                        now
                    ],
                )
                .expecting(1),
            ])
            .await;
        if result.is_err() {
            if let Some(row) = self
                .backend
                .query_opt(
                    "SELECT mutation_kind, expected_resource_version
                       FROM topology_operation_mutations
                      WHERE operation_id = ?1 AND idempotency_key = ?2",
                    &vals![operation_id, idempotency_key],
                )
                .await?
            {
                let recorded_kind: String = row.get(0)?;
                let recorded_expected: i64 = row.get(1)?;
                if recorded_kind == mutation_kind && recorded_expected == expected_version {
                    return self
                        .topology_operation(operation_id)
                        .await?
                        .context("mutated topology operation disappeared");
                }
                bail!("operation idempotency key was concurrently reused");
            }
            result?;
        }
        self.topology_operation(operation_id)
            .await?
            .context("mutated topology operation disappeared")
    }

    /// Every distinct store hash the registry's index references, sorted.
    ///
    /// The union of (a) the hash prefix of every `version_platforms`
    /// `store_path` basename — the text before the first `-` — and (b)
    /// every entry of the per-platform `refs` JSON arrays. Basenames with
    /// no `-` separator carry no extractable hash and are skipped.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn all_store_hashes(&self, registry_id: i64) -> Result<Vec<String>> {
        let rows = self
            .backend
            .query(
                "SELECT vp.store_path, vp.refs FROM version_platforms vp
             JOIN package_versions pv ON pv.id = vp.version_id
             JOIN packages p ON p.id = pv.package_id
             WHERE p.registry_id = ?1",
                &vals![registry_id],
            )
            .await?;
        let mut hashes = std::collections::BTreeSet::new();
        for row in &rows {
            let store_path: String = row.get(0)?;
            let refs_json: String = row.get(1)?;
            let basename = store_path.rsplit('/').next().unwrap_or(&store_path);
            if let Some((hash, _)) = basename.split_once('-') {
                hashes.insert(hash.to_string());
            }
            // The refs column is index-written JSON; tolerate (skip) a
            // malformed value the same way registry rows are read.
            let refs: Vec<String> = serde_json::from_str(&refs_json).unwrap_or_default();
            hashes.extend(refs);
        }
        Ok(hashes.into_iter().collect())
    }

    // -- index reads --------------------------------------------------------

    /// The index status for a registry.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn index_status(&self, registry_id: i64) -> Result<Option<IndexStatus>> {
        self.backend
            .query_opt(
                "SELECT state, error, last_indexed_commit, name, description, readme, indexed_at,
                        generation, content_digest
                 FROM registry_index WHERE registry_id = ?1",
                &vals![registry_id],
            )
            .await
            .context("loading index status")?
            .map(|row| {
                Ok(IndexStatus {
                    state: row.get(0)?,
                    error: row.get(1)?,
                    last_indexed_commit: row.get(2)?,
                    name: row.get(3)?,
                    description: row.get(4)?,
                    readme: row.get(5)?,
                    indexed_at: row.get(6)?,
                    generation: row.get(7)?,
                    content_digest: row.get(8)?,
                })
            })
            .transpose()
    }

    /// List every package in a registry with its newest indexed version.
    ///
    /// Used by the registry home, the indexer's package count, and the
    /// `ListPackages` RPC. For the anonymous browse UI — whose request cost an
    /// attacker controls by indexing an arbitrarily large registry — prefer
    /// [`Database::list_packages_capped`], which bounds the rows loaded.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_packages(&self, registry_id: i64) -> Result<Vec<PackageRow>> {
        let (rows, _truncated) = self.query_package_rows(registry_id, None).await?;
        Ok(rows)
    }

    /// List a registry's packages for the browse UI, capped at `limit` rows.
    ///
    /// Identical in shape to [`Database::list_packages`] but applies a DB-side
    /// `LIMIT` so a pathologically large registry cannot force the hub to
    /// materialize an unbounded package set per anonymous page view. Returns
    /// the (name-ordered) rows and a `truncated` flag that is `true` when the
    /// registry holds more packages than `limit` — the handler surfaces this as
    /// a "showing first N of many" indicator. The rich client-side filter still
    /// operates over the capped set.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_packages_capped(
        &self,
        registry_id: i64,
        limit: usize,
    ) -> Result<(Vec<PackageRow>, bool)> {
        self.query_package_rows(registry_id, Some(limit)).await
    }

    /// Single-query package listing shared by [`Database::list_packages`] and
    /// [`Database::list_packages_capped`].
    ///
    /// Joins each package to its newest version (`MAX(package_versions.id)`)
    /// and that version's platform artifacts in **one** round-trip — replacing
    /// the former per-package sub-query (an O(packages) N+1) with a single
    /// `LEFT JOIN`. Rows arrive ordered by package name then platform, so the
    /// per-package platform list and primary-platform closure size are folded
    /// in a single linear pass.
    ///
    /// When `limit` is `Some(n)`, the package set is bounded with a DB-side
    /// `LIMIT` over a name-ordered subquery; the returned flag is `true` when
    /// the registry actually holds more than `n` packages. With `None` every
    /// package is returned and the flag is always `false`.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    async fn query_package_rows(
        &self,
        registry_id: i64,
        limit: Option<usize>,
    ) -> Result<(Vec<PackageRow>, bool)> {
        // Bound the *packages* (not the joined platform rows) so the LIMIT
        // selects whole packages: filter to a capped name-ordered subset of
        // package ids, then join in their newest version's platforms. One
        // extra row beyond the cap is requested to detect truncation without a
        // second COUNT query.
        let probe = limit.map(|n| n.saturating_add(1) as i64);
        let rows = match probe {
            Some(probe) => {
                self.backend
                    .query(
                        "SELECT p.id, p.name, p.description, p.license,
                        (SELECT v.version FROM package_versions v
                         WHERE v.package_id = p.id ORDER BY v.id DESC LIMIT 1),
                        vp.platform, vp.closure_size
                 FROM (SELECT id, name, description, license
                       FROM packages
                       WHERE registry_id = ?1
                       ORDER BY name LIMIT ?2) p
                 LEFT JOIN version_platforms vp
                   ON vp.version_id = (SELECT MAX(v.id) FROM package_versions v
                                       WHERE v.package_id = p.id)
                 ORDER BY p.name, vp.platform",
                        &vals![registry_id, probe],
                    )
                    .await?
            }
            None => {
                self.backend
                    .query(
                        "SELECT p.id, p.name, p.description, p.license,
                        (SELECT v.version FROM package_versions v
                         WHERE v.package_id = p.id ORDER BY v.id DESC LIMIT 1),
                        vp.platform, vp.closure_size
                 FROM packages p
                 LEFT JOIN version_platforms vp
                   ON vp.version_id = (SELECT MAX(v.id) FROM package_versions v
                                       WHERE v.package_id = p.id)
                 WHERE p.registry_id = ?1
                 ORDER BY p.name, vp.platform",
                        &vals![registry_id],
                    )
                    .await?
            }
        };

        // Fold the joined rows into one [`PackageRow`] per package, in the
        // name order the query guarantees. A package with no platform
        // artifacts appears as a single row with NULL platform/closure.
        let mut out: Vec<PackageRow> = Vec::new();
        let mut current_id: Option<i64> = None;
        for row in &rows {
            let package_id: i64 = row.get(0)?;
            if current_id != Some(package_id) {
                current_id = Some(package_id);
                out.push(PackageRow {
                    name: row.get(1)?,
                    description: row.get(2)?,
                    license: row.get(3)?,
                    latest_version: row.get(4)?,
                    closure_size: None,
                    platforms: Vec::new(),
                });
            }
            // `out` is non-empty: the first iteration always pushes (its id
            // cannot equal the sentinel `None`), and later iterations only skip
            // the push when the current package's row is already on top.
            if let Some(entry) = out.last_mut() {
                if let Some(platform) = row.get::<Option<String>>(5)? {
                    entry.platforms.push(platform);
                    if entry.closure_size.is_none() {
                        entry.closure_size = row.get::<Option<u64>>(6)?;
                    }
                }
            }
        }

        // The probe row (cap + 1th package) signals truncation; drop it so the
        // caller sees exactly `limit` packages.
        let truncated = match limit {
            Some(n) if out.len() > n => {
                out.truncate(n);
                true
            }
            _ => false,
        };
        Ok((out, truncated))
    }

    /// Load one package's full detail.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn package_detail(
        &self,
        registry_id: i64,
        name: &str,
    ) -> Result<Option<PackageDetail>> {
        let header = self
            .backend
            .query_opt(
                "SELECT id, name, description, homepage, license, maintainer, sysroot
             FROM packages WHERE registry_id = ?1 AND name = ?2",
                &vals![registry_id, name],
            )
            .await?;
        let Some(header) = header else {
            return Ok(None);
        };
        let package_id: i64 = header.get(0)?;
        let mut detail = PackageDetail {
            name: header.get(1)?,
            description: header.get(2)?,
            homepage: header.get(3)?,
            license: header.get(4)?,
            maintainer: header.get(5)?,
            sysroot: header.get(6)?,
            versions: Vec::new(),
        };

        let version_rows = self
            .backend
            .query(
                "SELECT id, version, previous FROM package_versions
             WHERE package_id = ?1 ORDER BY id DESC",
                &vals![package_id],
            )
            .await?;
        let versions = version_rows
            .iter()
            .map(|row| {
                Ok((
                    row.get::<i64>(0)?,
                    row.get::<String>(1)?,
                    row.get::<Option<String>>(2)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;

        for (version_id, version, previous) in versions {
            let platform_rows = self
                .backend
                .query(
                    "SELECT platform, store_path, nar_hash, nar_size, closure_size, refs, images,
                        source_drv
                 FROM version_platforms WHERE version_id = ?1 ORDER BY platform",
                    &vals![version_id],
                )
                .await?;
            let platforms = platform_rows
                .iter()
                .map(|row| {
                    // refs/images are index-written JSON; tolerate (skip) a
                    // malformed value the same way registry rows are read.
                    let refs_json: String = row.get(5)?;
                    let images_json: String = row.get(6)?;
                    Ok(PlatformDetail {
                        platform: row.get(0)?,
                        store_path: row.get(1)?,
                        nar_hash: row.get(2)?,
                        nar_size: row.get(3)?,
                        closure_size: row.get(4)?,
                        source_drv: row.get(7)?,
                        refs: serde_json::from_str(&refs_json).unwrap_or_default(),
                        images: serde_json::from_str(&images_json).unwrap_or_default(),
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            detail.versions.push(VersionDetail {
                version,
                previous,
                platforms,
            });
        }
        Ok(Some(detail))
    }

    /// Lists signed direct-delivery images belonging to verified releases.
    ///
    /// The rows come only from exact commits named by verified signed release
    /// tags. Default-branch package metadata is intentionally not consulted.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure or malformed signed image metadata.
    pub async fn list_system_images(&self, registry_id: i64) -> Result<Vec<IndexedSystemImage>> {
        let rows = self
            .backend
            .query(
                "SELECT image.package_name, image.release, image.platform,
                        image.format, image.delivery, image.catalog_digest
                   FROM registry_system_images image
                   JOIN releases rel
                     ON rel.registry_id = image.registry_id
                    AND rel.semver = image.release
                    AND rel.commit_oid = image.source_commit
                    AND rel.tag_oid = image.verified_tag_oid
                   JOIN registry_index idx
                     ON idx.registry_id = image.registry_id
                    AND idx.state = 'fresh'
                  WHERE image.registry_id = ?1
                  ORDER BY image.release DESC, image.package_name,
                           image.platform, image.format",
                &vals![registry_id],
            )
            .await?;
        let mut images = Vec::new();
        for row in &rows {
            let package: String = row.get(0)?;
            let release: String = row.get(1)?;
            let platform: String = row.get(2)?;
            let format: String = row.get(3)?;
            let encoded: String = row.get(4)?;
            let catalog_digest: String = row.get(5)?;
            if catalog_digest.len() != 64 {
                bail!("indexed signed image catalog has invalid digest identity");
            }
            let delivery: aos_registry_surface::manifest::ImageDelivery =
                serde_json::from_str(&encoded)
                    .context("decoding signed image delivery metadata")?;
            delivery
                .validate(&format, &release, &platform)
                .context("validating indexed signed image delivery metadata")?;
            if !self
                .system_image_delivery_ready(registry_id, &delivery)
                .await?
            {
                continue;
            }
            images.push(IndexedSystemImage {
                package,
                release,
                platform,
                format,
                delivery,
            });
        }
        Ok(images)
    }

    /// Resolves one signed image by its canonical immutable object key.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure, malformed signed metadata, or a
    /// duplicate object key in the authenticated catalog.
    pub async fn system_image_object_by_key(
        &self,
        registry_id: i64,
        object_key: &str,
    ) -> Result<Option<IndexedSystemImageObject>> {
        let mut matches = self
            .list_system_images(registry_id)
            .await?
            .into_iter()
            .filter_map(|image| {
                if image.delivery.object_key == object_key {
                    Some(IndexedSystemImageObject::Disk(image))
                } else if image.delivery.image_info.object_key == object_key {
                    Some(IndexedSystemImageObject::ImageInfo(image))
                } else {
                    None
                }
            });
        let found = matches.next();
        if matches.next().is_some() {
            bail!("signed image object key is ambiguous");
        }
        Ok(found)
    }

    /// Lists immutable disk and image-info object keys rooted by signed releases.
    ///
    /// The returned set is the registry-image contribution to retention and GC:
    /// [`Self::tombstone_surface_object`] refuses every object in this set.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_system_image_root_keys(&self, registry_id: i64) -> Result<Vec<String>> {
        self.backend
            .query(
                "SELECT DISTINCT object.object_key
                   FROM registry_image_roots root
                   JOIN surface_objects object
                     ON object.id = root.surface_object_id
                    AND object.registry_id = root.registry_id
                  WHERE root.registry_id = ?1
                  ORDER BY object.object_key",
                &vals![registry_id],
            )
            .await?
            .iter()
            .map(|row| row.get(0))
            .collect()
    }

    /// Lists the exact signed identities of all currently rooted image objects.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_system_image_roots(
        &self,
        registry_id: i64,
    ) -> Result<Vec<(String, String, i64)>> {
        self.backend
            .query(
                "SELECT DISTINCT object.object_key, root.expected_hash, root.expected_size
                   FROM registry_image_roots root
                   JOIN surface_objects object
                     ON object.id = root.surface_object_id
                    AND object.registry_id = root.registry_id
                  WHERE root.registry_id = ?1
                  ORDER BY object.object_key",
                &vals![registry_id],
            )
            .await?
            .iter()
            .map(|row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))
            .collect()
    }

    /// Returns whether the last good index contains a signed image catalog.
    ///
    /// The indexer uses this to disable its metadata-only incremental path:
    /// every refresh of an image-bearing registry must re-read and re-hash the
    /// exact release objects before restoring serving visibility.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn has_system_image_catalog(&self, registry_id: i64) -> Result<bool> {
        Ok(self
            .backend
            .query_opt(
                "SELECT 1 FROM registry_system_images WHERE registry_id = ?1 LIMIT 1",
                &vals![registry_id],
            )
            .await?
            .is_some())
    }

    /// Records exact storage presence for signed image roots on the indexed placement.
    ///
    /// # Errors
    ///
    /// Returns an error when the placement is not on the registry, an object is
    /// not a matching signed root, or the database write fails.
    pub async fn record_registry_image_presence(
        &self,
        registry_id: i64,
        placement_id: i64,
        objects: &[VerifiedRegistryImageObject],
        observed_at: i64,
    ) -> Result<()> {
        let statements = Self::registry_image_presence_statements(
            registry_id,
            placement_id,
            objects,
            observed_at,
        )?;
        self.backend.checked_batch(&statements).await
    }

    fn registry_image_presence_statements(
        registry_id: i64,
        placement_id: i64,
        objects: &[VerifiedRegistryImageObject],
        observed_at: i64,
    ) -> Result<Vec<CheckedStatement>> {
        let generation = observed_at.max(1);
        let mut statements = Vec::with_capacity(objects.len().saturating_mul(3) + 2);
        for object in objects {
            if object.byte_size <= 0 {
                bail!("verified registry image object size must be positive");
            }
            let is_snapshot =
                object.strong_etag == format!("\"snapshot-sha256-{}\"", object.sha256);
            if is_snapshot {
                statements.push(
                    Statement::new(
                        "INSERT INTO image_snapshots(digest, byte_size, state, created_at)
                     VALUES (?1, ?2, 'live', ?3)
                     ON CONFLICT(digest) DO UPDATE SET
                       state = 'live'
                     WHERE image_snapshots.byte_size = excluded.byte_size",
                        vals![object.sha256, object.byte_size, observed_at].to_vec(),
                    )
                    .unchecked(),
                );
                statements.push(
                    Statement::new(
                        "DELETE FROM image_snapshot_references
                     WHERE digest = ?1 AND registry_id = ?2
                       AND placement_id = ?3 AND object_key = ?4",
                        vals![object.sha256, registry_id, placement_id, object.object_key].to_vec(),
                    )
                    .unchecked(),
                );
                statements.push(
                    Statement::new(
                        "INSERT INTO image_snapshot_references
                       (digest, registry_id, placement_id, object_key)
                     SELECT digest, ?2, ?3, ?4 FROM image_snapshots
                     WHERE digest = ?1 AND byte_size = ?5",
                        vals![
                            object.sha256,
                            registry_id,
                            placement_id,
                            object.object_key,
                            object.byte_size
                        ]
                        .to_vec(),
                    )
                    .expecting(1),
                );
            }
            statements.push(
                Statement::new(
                    "DELETE FROM object_placements
                 WHERE registry_id = ?1 AND placement_id = ?2
                   AND surface_object_id IN (
                     SELECT id FROM surface_objects
                     WHERE registry_id = ?1 AND object_key = ?3)",
                    vals![registry_id, placement_id, object.object_key].to_vec(),
                )
                .unchecked(),
            );
            statements.push(
                Statement::new(
                    "INSERT INTO object_placements
                 (surface_object_id, cache_id, registry_id, placement_id,
                  state, observed_hash, observed_size, etag,
                  observed_inventory_generation, observed_at)
                 SELECT root.surface_object_id, NULL, root.registry_id, placement.id,
                        'present', ?4, ?5, ?6, ?7, ?7
                 FROM registry_image_roots root
                 JOIN surface_objects object
                   ON object.id = root.surface_object_id
                  AND object.registry_id = root.registry_id
                 JOIN surface_placements placement
                   ON placement.id = ?2 AND placement.registry_id = root.registry_id
                 WHERE root.registry_id = ?1 AND object.object_key = ?3
                   AND root.expected_hash = ?4 AND root.expected_size = ?5
                   AND object.content_hash = ?4 AND object.size = ?5
                   AND (?8 = 0 OR EXISTS (
                     SELECT 1 FROM image_snapshot_references reference
                     WHERE reference.digest = ?4 AND reference.registry_id = ?1
                       AND reference.placement_id = ?2 AND reference.object_key = ?3))
                 ",
                    vals![
                        registry_id,
                        placement_id,
                        object.object_key,
                        object.sha256,
                        object.byte_size,
                        object.strong_etag,
                        generation,
                        is_snapshot
                    ]
                    .to_vec(),
                )
                .expecting(1),
            );
        }
        statements.push(
            Statement::new(
                "DELETE FROM image_snapshot_references
             WHERE registry_id = ?1 AND NOT EXISTS (
               SELECT 1 FROM registry_image_roots root
               JOIN surface_objects object ON object.id = root.surface_object_id
               WHERE root.registry_id = image_snapshot_references.registry_id
                 AND object.object_key = image_snapshot_references.object_key
                 AND root.expected_hash = image_snapshot_references.digest)",
                vals![registry_id].to_vec(),
            )
            .unchecked(),
        );
        statements.push(
            Statement::new(
                "UPDATE image_snapshots SET state = 'collectible'
             WHERE NOT EXISTS (
               SELECT 1 FROM image_snapshot_references reference
               WHERE reference.digest = image_snapshots.digest)",
                Vec::new(),
            )
            .unchecked(),
        );
        Ok(statements)
    }

    /// Returns the indexed strong version for one image object placement.
    pub async fn registry_image_placement_etag(
        &self,
        registry_id: i64,
        placement_id: i64,
        object_key: &str,
    ) -> Result<Option<String>> {
        self.backend
            .query_opt(
                "SELECT presence.etag
                 FROM object_placements presence
                 JOIN surface_objects object ON object.id = presence.surface_object_id
                 WHERE presence.registry_id = ?1 AND presence.placement_id = ?2
                   AND object.object_key = ?3 AND presence.state = 'present'
                   AND presence.etag IS NOT NULL",
                &vals![registry_id, placement_id, object_key],
            )
            .await?
            .map(|row| row.get(0))
            .transpose()
    }

    /// Lists Hub-private image snapshots with zero live references.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn collectible_image_snapshots(&self, limit: i64) -> Result<Vec<(String, i64)>> {
        let now = unix_now();
        let rows = self
            .backend
            .query(
                "SELECT digest, byte_size FROM image_snapshots snapshot
                 WHERE NOT EXISTS (
                   SELECT 1 FROM image_snapshot_references reference
                   WHERE reference.digest = snapshot.digest)
                   AND NOT EXISTS (
                     SELECT 1 FROM image_snapshot_leases lease
                     WHERE lease.digest = snapshot.digest AND lease.expires_at > ?2)
                 ORDER BY digest LIMIT ?1",
                &vals![limit, now],
            )
            .await?;
        rows.iter()
            .map(|row| Ok((row.get(0)?, row.get(1)?)))
            .collect()
    }

    /// Returns every snapshot digest tracked by durable GC state.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn known_image_snapshot_digests(&self) -> Result<std::collections::HashSet<String>> {
        Ok(self
            .backend
            .query("SELECT digest FROM image_snapshots", &[])
            .await?
            .iter()
            .map(|row| row.get(0))
            .collect::<Result<_>>()?)
    }

    /// Returns all durable snapshot identities for native startup validation.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn known_image_snapshots(&self) -> Result<Vec<(String, i64)>> {
        self.backend
            .query(
                "SELECT digest, byte_size FROM image_snapshots ORDER BY digest",
                &[],
            )
            .await?
            .iter()
            .map(|row| Ok((row.get(0)?, row.get(1)?)))
            .collect()
    }

    /// Reports whether a snapshot already has durable registry-placement roots.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn image_snapshot_has_references(&self, digest: &str) -> Result<bool> {
        Ok(self
            .backend
            .query_opt(
                "SELECT 1 FROM image_snapshot_references WHERE digest = ?1 LIMIT 1",
                &vals![digest],
            )
            .await?
            .is_some())
    }

    /// Removes expired in-flight snapshot leases.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn prune_expired_image_snapshot_leases(&self) -> Result<u64> {
        Ok(self
            .backend
            .execute(
                "DELETE FROM image_snapshot_leases WHERE expires_at <= ?1",
                &vals![unix_now()],
            )
            .await?)
    }

    /// Forgets a physically deleted snapshot only while it remains unreferenced.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn forget_collectible_image_snapshot(&self, digest: &str) -> Result<bool> {
        let now = unix_now();
        Ok(self
            .backend
            .execute(
                "DELETE FROM image_snapshots
                 WHERE digest = ?1 AND NOT EXISTS (
                   SELECT 1 FROM image_snapshot_references reference
                   WHERE reference.digest = image_snapshots.digest)
                   AND NOT EXISTS (
                     SELECT 1 FROM image_snapshot_leases lease
                     WHERE lease.digest = image_snapshots.digest AND lease.expires_at > ?2)",
                &vals![digest, now],
            )
            .await?
            == 1)
    }

    /// Protects a verified snapshot while indexing or a response is in flight.
    ///
    /// A successful registry-presence transaction replaces this transient
    /// protection with durable registry/placement references. Expiration makes
    /// an interrupted request or crashed process self-cleaning.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid snapshot metadata or a database failure.
    pub async fn lease_image_snapshot(
        &self,
        lease_id: &str,
        digest: &str,
        byte_size: i64,
        expires_at: i64,
    ) -> Result<()> {
        if lease_id.is_empty()
            || lease_id.len() > 64
            || digest.len() != 64
            || !digest
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
            || byte_size <= 0
            || expires_at <= unix_now()
        {
            bail!("invalid image snapshot lease identity, digest, size, or expiry");
        }
        self.backend
            .batch(&[
                Statement::new(
                    "INSERT INTO image_snapshots(digest, byte_size, state, created_at)
                     VALUES (?1, ?2, 'live', ?3)
                     ON CONFLICT(digest) DO UPDATE SET
                       state = 'live'
                     WHERE image_snapshots.byte_size = excluded.byte_size",
                    vals![digest, byte_size, unix_now()].to_vec(),
                ),
                Statement::new(
                    "INSERT INTO image_snapshot_leases(lease_id, digest, expires_at)
                     SELECT ?1, digest, ?3 FROM image_snapshots
                     WHERE digest = ?2 AND byte_size = ?4",
                    vals![lease_id, digest, expires_at, byte_size].to_vec(),
                ),
            ])
            .await?;
        let leased = self
            .backend
            .query_opt(
                "SELECT 1 FROM image_snapshot_leases
                 WHERE lease_id = ?1 AND digest = ?2",
                &vals![lease_id, digest],
            )
            .await?
            .is_some();
        if !leased {
            bail!("image snapshot digest was already recorded with a different size");
        }
        Ok(())
    }

    /// Releases one exact in-flight snapshot lease without affecting peers.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn release_image_snapshot_lease(&self, lease_id: &str) -> Result<bool> {
        Ok(self
            .backend
            .execute(
                "DELETE FROM image_snapshot_leases WHERE lease_id = ?1",
                &vals![lease_id],
            )
            .await?
            == 1)
    }

    /// Releases an exact set of in-flight snapshot leases atomically.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn release_image_snapshot_leases(&self, lease_ids: &[String]) -> Result<()> {
        if lease_ids.is_empty() {
            return Ok(());
        }
        let statements = lease_ids
            .iter()
            .map(|lease_id| {
                Statement::new(
                    "DELETE FROM image_snapshot_leases WHERE lease_id = ?1",
                    vals![lease_id].to_vec(),
                )
            })
            .collect::<Vec<_>>();
        self.backend.batch(&statements).await
    }

    async fn system_image_delivery_ready(
        &self,
        registry_id: i64,
        delivery: &aos_registry_surface::manifest::ImageDelivery,
    ) -> Result<bool> {
        for (key, hash, size) in [
            (
                delivery.object_key.as_str(),
                delivery.sha256.as_str(),
                delivery.byte_size,
            ),
            (
                delivery.image_info.object_key.as_str(),
                delivery.image_info.sha256.as_str(),
                delivery.image_info.byte_size,
            ),
        ] {
            let size =
                i64::try_from(size).context("signed image object size exceeds database range")?;
            let present = self
                .backend
                .query_opt(
                    "SELECT 1 FROM registry_image_roots root
                     JOIN surface_objects object ON object.id = root.surface_object_id
                     JOIN object_placements presence
                       ON presence.surface_object_id = object.id
                      AND presence.registry_id = object.registry_id
                     JOIN surface_placement_effective placement
                       ON placement.id = presence.placement_id
                      AND placement.registry_id = object.registry_id
                     WHERE root.registry_id = ?1 AND object.object_key = ?2
                       AND root.expected_hash = ?3 AND root.expected_size = ?4
                       AND presence.state = 'present'
                       AND presence.observed_hash = ?3 AND presence.observed_size = ?4
                       AND placement.kind = 'complete'
                       AND placement.desired_state = 'active'
                       AND placement.state IN ('ready', 'degraded')
                       AND placement.effective_read_enabled = 1
                     LIMIT 1",
                    &vals![registry_id, key, hash, size],
                )
                .await?
                .is_some();
            if !present {
                return Ok(false);
            }
        }
        Ok(true)
    }

    /// Build the registry's store-hash → (package name, version) index.
    ///
    /// Loads every `version_platforms` row once and maps the store-path hash
    /// prefix (the basename text before the first `-`) to the owning package's
    /// name and version. When two artifacts share a hash prefix the first
    /// `ORDER BY` winner is kept; the platform triple is dropped because a
    /// dependency edge points at a store path, not a platform.
    ///
    /// This is the dialect-safe primitive the closure-browser reads:
    /// [`resolve_reference_names`](Self::resolve_reference_names) and
    /// [`reverse_dependencies`](Self::reverse_dependencies) both resolve in
    /// Rust against this map rather than relying on backend JSON functions.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    async fn store_hash_index(
        &self,
        registry_id: i64,
    ) -> Result<std::collections::HashMap<String, (String, String)>> {
        let rows = self
            .backend
            .query(
                "SELECT vp.store_path, p.name, pv.version
             FROM version_platforms vp
             JOIN package_versions pv ON pv.id = vp.version_id
             JOIN packages p ON p.id = pv.package_id
             WHERE p.registry_id = ?1
             ORDER BY p.name, pv.id DESC",
                &vals![registry_id],
            )
            .await?;
        let mut index = std::collections::HashMap::new();
        for row in &rows {
            let store_path: String = row.get(0)?;
            let name: String = row.get(1)?;
            let version: String = row.get(2)?;
            let basename = store_path.rsplit('/').next().unwrap_or(&store_path);
            if let Some((hash, _)) = basename.split_once('-') {
                index.entry(hash.to_string()).or_insert((name, version));
            }
        }
        Ok(index)
    }

    /// Resolve store-hash prefixes to the packages that publish them.
    ///
    /// For each hash in `hashes`, returns `(hash, name, version)` where `name`
    /// and `version` are `Some` when some package in `registry_id` publishes an
    /// artifact whose store-path hash prefix equals that hash, and `None` when
    /// the hash belongs to a store path outside this registry's package set
    /// (e.g. a stdenv closure dependency). Output order matches `hashes`.
    ///
    /// This turns the opaque `refs` closure-edge list on the package page into
    /// a legible dependency list: resolvable hashes link to their package page,
    /// unresolvable ones fall back to their narinfo permalink. Resolution runs
    /// in Rust against `store_hash_index`, so it is
    /// independent of the backend's JSON-function dialect.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn resolve_reference_names(
        &self,
        registry_id: i64,
        hashes: &[String],
    ) -> Result<Vec<ResolvedReference>> {
        let index = self.store_hash_index(registry_id).await?;
        Ok(hashes
            .iter()
            .map(|hash| match index.get(hash) {
                Some((name, version)) => (hash.clone(), Some(name.clone()), Some(version.clone())),
                None => (hash.clone(), None, None),
            })
            .collect())
    }

    /// Find the packages whose runtime closure references `store_hash`.
    ///
    /// Returns `(name, version)` for every artifact in `registry_id` whose
    /// `refs` JSON array contains `store_hash` — the reverse of the dependency
    /// edge, i.e. "required by". Results are de-duplicated by package name
    /// (keeping the newest version seen) and sorted by name, so a package that
    /// depends on the target across several versions appears once.
    ///
    /// The `refs` column is index-written JSON; rows whose value does not parse
    /// as a string array are skipped, matching how the rest of the index reads
    /// tolerate malformed JSON.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn reverse_dependencies(
        &self,
        registry_id: i64,
        store_hash: &str,
    ) -> Result<Vec<(String, String)>> {
        let rows = self
            .backend
            .query(
                "SELECT p.name, pv.version, vp.refs
             FROM version_platforms vp
             JOIN package_versions pv ON pv.id = vp.version_id
             JOIN packages p ON p.id = pv.package_id
             WHERE p.registry_id = ?1
             ORDER BY p.name, pv.id DESC",
                &vals![registry_id],
            )
            .await?;
        // De-duplicate by name, keeping the first (newest, by the ORDER BY)
        // version that references the target hash.
        let mut seen = std::collections::BTreeMap::new();
        for row in &rows {
            let name: String = row.get(0)?;
            let version: String = row.get(1)?;
            let refs_json: String = row.get(2)?;
            let refs: Vec<String> = serde_json::from_str(&refs_json).unwrap_or_default();
            if refs.iter().any(|r| r == store_hash) {
                seen.entry(name).or_insert(version);
            }
        }
        Ok(seen.into_iter().collect())
    }

    /// The store-path hash of a package's latest version on a chosen platform.
    ///
    /// Returns the basename hash prefix (text before the first `-`) of the
    /// newest version's artifact, preferring the given `platform` and otherwise
    /// falling back to whichever platform sorts first. Returns `None` when the
    /// package has no versions, no platform artifacts, or a store path with no
    /// extractable hash. This is the key used to look up the package's
    /// "required by" set via [`reverse_dependencies`](Self::reverse_dependencies).
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn primary_store_hash(
        &self,
        registry_id: i64,
        name: &str,
        platform: &str,
    ) -> Result<Option<String>> {
        let rows = self
            .backend
            .query(
                "SELECT vp.platform, vp.store_path
             FROM version_platforms vp
             JOIN package_versions pv ON pv.id = vp.version_id
             JOIN packages p ON p.id = pv.package_id
             WHERE p.registry_id = ?1 AND p.name = ?2
               AND pv.id = (SELECT MAX(v.id) FROM package_versions v
                            WHERE v.package_id = p.id)
             ORDER BY vp.platform",
                &vals![registry_id, name],
            )
            .await?;
        let mut fallback: Option<String> = None;
        for row in &rows {
            let row_platform: String = row.get(0)?;
            let store_path: String = row.get(1)?;
            let basename = store_path.rsplit('/').next().unwrap_or(&store_path);
            let Some((hash, _)) = basename.split_once('-') else {
                continue;
            };
            if row_platform == platform {
                return Ok(Some(hash.to_string()));
            }
            fallback.get_or_insert_with(|| hash.to_string());
        }
        Ok(fallback)
    }

    /// List channels with their full partition maps.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_channels(&self, registry_id: i64) -> Result<Vec<ChannelSummary>> {
        let channel_rows = self
            .backend
            .query(
                "SELECT id, name, frontier FROM channels
                 WHERE registry_id = ?1 AND active = 1 ORDER BY name",
                &vals![registry_id],
            )
            .await?;
        let channels = channel_rows
            .iter()
            .map(|row| {
                Ok((
                    row.get::<i64>(0)?,
                    row.get::<String>(1)?,
                    row.get::<Option<String>>(2)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;

        let mut out = Vec::with_capacity(channels.len());
        for (channel_id, name, frontier) in channels {
            let mut partitions = vec![None; 256];
            let rows = self
                .backend
                .query(
                    "SELECT bucket, release FROM channel_partitions WHERE channel_id = ?1",
                    &vals![channel_id],
                )
                .await?;
            for row in &rows {
                let bucket: i64 = row.get(0)?;
                let release: String = row.get(1)?;
                if let Some(slot) = partitions.get_mut(bucket as usize) {
                    *slot = Some(release);
                }
            }
            out.push(ChannelSummary {
                name,
                frontier,
                partitions,
            });
        }
        Ok(out)
    }

    /// List verified releases, newest first.
    ///
    /// Naturally bounded: the indexer writes at most
    /// the hub's `indexer::MAX_RELEASE_TAGS` (1024) release rows
    /// per registry, so the result set cannot grow without bound and needs no
    /// additional DB-side `LIMIT`.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_releases(&self, registry_id: i64) -> Result<Vec<ReleaseRow>> {
        let rows = self
            .backend
            .query(
                "SELECT semver, tag_oid, commit_oid, signer, tagged_at, pack_present
             FROM releases WHERE registry_id = ?1 ORDER BY tagged_at DESC, semver DESC",
                &vals![registry_id],
            )
            .await?;
        rows.iter()
            .map(|row| {
                Ok(ReleaseRow {
                    semver: row.get(0)?,
                    tag_oid: row.get(1)?,
                    commit_oid: row.get(2)?,
                    signer: row.get(3)?,
                    tagged_at: row.get(4)?,
                    pack_present: row.get(5)?,
                })
            })
            .collect()
    }

    /// Lists verified releases that own a complete immutable artifact snapshot.
    ///
    /// A complete empty snapshot is returned with an empty artifact vector;
    /// releases with missing, building, or failed snapshots are excluded.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_retention_release_snapshots(
        &self,
        registry_id: i64,
    ) -> Result<Vec<RetentionReleaseSnapshotRecord>> {
        let rows = self
            .backend
            .query(
                "SELECT rel.id, rel.semver, rel.tag_oid, rel.tagged_at,
                        ras.snapshot_id, ras.manifest_digest,
                        rsa.package_name, rsa.package_version, rsa.platform,
                        rsa.artifact_kind, rsa.store_path, rsa.store_hash
                 FROM releases rel
                 JOIN release_artifact_snapshot_heads head
                   ON head.release_id = rel.id AND head.registry_id = rel.registry_id
                 JOIN release_artifact_snapshots ras
                   ON ras.snapshot_id = head.complete_artifact_snapshot_id
                  AND ras.release_id = head.release_id
                  AND ras.registry_id = head.registry_id
                  AND ras.state = 'complete'
                  AND ras.source_commit = rel.commit_oid
                  AND ras.verified_tag_oid = rel.tag_oid
                 LEFT JOIN release_artifacts rsa
                   ON rsa.snapshot_id = ras.snapshot_id
                  AND rsa.release_id = ras.release_id
                  AND rsa.registry_id = ras.registry_id
                 WHERE rel.registry_id = ?1
                 ORDER BY rel.id, rsa.package_name, rsa.package_version,
                          rsa.platform, rsa.artifact_kind, rsa.store_hash",
                &vals![registry_id],
            )
            .await?;
        let mut releases = Vec::<RetentionReleaseSnapshotRecord>::new();
        for row in &rows {
            let release_id: i64 = row.get(0)?;
            if releases.last().map(|release| release.release_id) != Some(release_id) {
                releases.push(RetentionReleaseSnapshotRecord {
                    release_id,
                    tag: row.get(1)?,
                    verified_tag_oid: row.get(2)?,
                    tagged_at: row.get(3)?,
                    snapshot_id: row.get(4)?,
                    manifest_digest: row.get(5)?,
                    artifacts: Vec::new(),
                });
            }
            let package_name: Option<String> = row.get(6)?;
            if let Some(package_name) = package_name {
                let release = releases
                    .last_mut()
                    .context("release snapshot grouping lost its parent row")?;
                release.artifacts.push(ReleaseSnapshotArtifact {
                    package_name,
                    package_version: row.get(7)?,
                    platform: row.get(8)?,
                    artifact_kind: row.get(9)?,
                    store_path: row.get(10)?,
                    store_hash: row.get(11)?,
                });
            }
        }
        Ok(releases)
    }

    /// Lists live channel partitions whose target owns a complete release snapshot.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_retention_channel_partitions(
        &self,
        registry_id: i64,
    ) -> Result<Vec<RetentionChannelPartitionRecord>> {
        let releases = self.list_retention_release_snapshots(registry_id).await?;
        let by_id = releases
            .into_iter()
            .map(|release| (release.release_id, release))
            .collect::<std::collections::BTreeMap<_, _>>();
        let rows = self
            .backend
            .query(
                "SELECT ch.id, ch.name, cp.bucket, rel.id, rel.semver
                 FROM channels ch
                 JOIN channel_partitions cp ON cp.channel_id = ch.id
                 JOIN releases rel ON rel.registry_id = ch.registry_id
                   AND rel.semver = cp.release
                 WHERE ch.registry_id = ?1 AND ch.active = 1
                 ORDER BY ch.name, cp.bucket",
                &vals![registry_id],
            )
            .await?;
        let mut partitions = Vec::new();
        for row in &rows {
            let release_id: i64 = row.get(3)?;
            let Some(release) = by_id.get(&release_id) else {
                continue;
            };
            partitions.push(RetentionChannelPartitionRecord {
                channel_id: row.get(0)?,
                channel_name: row.get(1)?,
                bucket: row.get(2)?,
                release_id,
                release_tag: row.get(4)?,
                snapshot_id: release.snapshot_id.clone(),
                artifacts: release.artifacts.clone(),
            });
        }
        Ok(partitions)
    }

    /// Lists output and image artifacts in the current verified catalog.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure or malformed indexed image JSON.
    pub async fn list_current_catalog_retention_artifacts(
        &self,
        registry_id: i64,
    ) -> Result<Vec<ReleaseSnapshotArtifact>> {
        let rows = self
            .backend
            .query(
                "SELECT p.name, pv.version, vp.platform, vp.store_path, vp.images
                 FROM version_platforms vp
                 JOIN package_versions pv ON pv.id = vp.version_id
                 JOIN packages p ON p.id = pv.package_id
                 WHERE p.registry_id = ?1
                 ORDER BY p.name, pv.version, vp.platform",
                &vals![registry_id],
            )
            .await?;
        let mut artifacts = Vec::new();
        for row in &rows {
            let package_name: String = row.get(0)?;
            let package_version: String = row.get(1)?;
            let platform: String = row.get(2)?;
            let store_path: String = row.get(3)?;
            artifacts.push(ReleaseSnapshotArtifact {
                package_name: package_name.clone(),
                package_version: package_version.clone(),
                platform: platform.clone(),
                artifact_kind: "output".to_string(),
                store_hash: store_hash_component(&store_path),
                store_path,
            });
            let images: String = row.get(4)?;
            for image in serde_json::from_str::<Vec<serde_json::Value>>(&images)? {
                let image_path = image
                    .get("store_path")
                    .and_then(serde_json::Value::as_str)
                    .context("indexed image is missing store_path")?;
                artifacts.push(ReleaseSnapshotArtifact {
                    package_name: package_name.clone(),
                    package_version: package_version.clone(),
                    platform: platform.clone(),
                    artifact_kind: "image".to_string(),
                    store_hash: store_hash_component(image_path),
                    store_path: image_path.to_string(),
                });
            }
        }
        artifacts.sort_by(|left, right| {
            (
                &left.package_name,
                &left.package_version,
                &left.platform,
                &left.artifact_kind,
                &left.store_hash,
            )
                .cmp(&(
                    &right.package_name,
                    &right.package_version,
                    &right.platform,
                    &right.artifact_kind,
                    &right.store_hash,
                ))
        });
        artifacts.dedup();
        Ok(artifacts)
    }

    /// The `info/refs` digest the current index was built from, when set.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn refs_digest(&self, registry_id: i64) -> Result<Option<String>> {
        let digest: Option<Option<String>> = self
            .backend
            .query_opt(
                "SELECT refs_digest FROM registry_index WHERE registry_id = ?1",
                &vals![registry_id],
            )
            .await
            .context("loading refs digest")?
            .map(|row| row.get::<Option<String>>(0))
            .transpose()?;
        Ok(digest.flatten())
    }

    /// The roster as `(key_id, public_key, status)` rows.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_roster(&self, registry_id: i64) -> Result<Vec<(String, String, String)>> {
        let rows = self
            .backend
            .query(
                "SELECT key_id, public_key, status FROM key_rosters
             WHERE registry_id = ?1 ORDER BY status, key_id",
                &vals![registry_id],
            )
            .await?;
        rows.iter()
            .map(|row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))
            .collect()
    }

    /// The committed cache-stack expression for a registry, parsed.
    ///
    /// Returns the stored stack ([`crate::stack::StackNode`]) when the
    /// registry's committed `registry.toml` carried a `[caches]` stack at index
    /// time, or `None` when it declared no cache stack.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure, or when the stored stack JSON
    /// fails to parse (an internal-consistency error — the indexer only ever
    /// stores well-formed JSON).
    pub async fn registry_cache_stack(
        &self,
        registry_id: i64,
    ) -> Result<Option<crate::stack::StackNode>> {
        let json: Option<String> = self
            .backend
            .query_opt(
                "SELECT cache_stack FROM registry_index WHERE registry_id = ?1",
                &vals![registry_id],
            )
            .await
            .context("loading registry cache stack")?
            .map(|row| row.get::<Option<String>>(0))
            .transpose()?
            .flatten();
        match json {
            Some(json) => Ok(Some(crate::stack::StackNode::from_json(&json)?)),
            None => Ok(None),
        }
    }

    // -- tenancy: orgs and projects -----------------------------------------

    /// Create an organization; returns its new id.
    ///
    /// The `slug` is validated against the canonical single-segment ruleset
    /// ([`crate::domain::iam::validate_org_slug`]) as a persistence-layer
    /// backstop: an org slug is a single URL/scope path segment, so it may
    /// not contain `/` or any out-of-charset character. This prevents any
    /// caller — RPC, console, or CLI — from writing a slug that
    /// [`crate::domain::Scope::parse`] would later normalize into an
    /// unintended ancestor scope (sec CR-2).
    ///
    /// # Errors
    ///
    /// Returns an error when `slug` fails validation, and on database
    /// failure, including a unique-constraint violation when `slug` is
    /// already taken.
    pub async fn create_org(&self, slug: &str, name: &str) -> Result<i64> {
        crate::domain::iam::validate_org_slug(slug)
            .map_err(|e| anyhow::anyhow!("invalid org slug '{slug}': {e}"))?;
        let org_id = self.max_id("orgs").await? + 1;
        let consumer_scope_key = format!("org:{}", uuid::Uuid::new_v4().simple());
        let now = unix_now();
        let event_id = format!("grant-event:{}", uuid::Uuid::new_v4().simple());
        self.backend
            .checked_batch(&[
                Statement::new(
                    "INSERT INTO orgs (id, stable_id, slug, name, created_at, updated_at)
                     VALUES (?1, ?2, ?3, ?4, ?5, ?5)",
                    vals![org_id, consumer_scope_key, slug, name, now],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO authorization_scopes
                     (scope_key, kind, org_id, parent_scope_key, resource_stable_id, created_at)
                     VALUES (?1, 'organization', ?2, 'instance', ?1, ?3)",
                    vals![consumer_scope_key, org_id, now],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO authorization_scope_ancestors
                     (descendant_scope_key, ancestor_scope_key, depth)
                     VALUES (?1, ?1, 0)",
                    vals![consumer_scope_key],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO authorization_scope_ancestors
                     (descendant_scope_key, ancestor_scope_key, depth)
                     SELECT ?1, ancestor_scope_key, depth + 1
                       FROM authorization_scope_ancestors
                      WHERE descendant_scope_key = 'instance'",
                    vals![consumer_scope_key],
                )
                .unchecked(),
                Statement::new(
                    "INSERT INTO network_boundary_consumer_scopes
                     (boundary_id, consumer_scope_key, grant_generation, grant_kind,
                      state, granted_by, granted_at, resource_version)
                     VALUES ('instance:public', ?1, 1, 'instance_default',
                       'active', 'system:org-create', ?2, 1)",
                    vals![consumer_scope_key, now],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO storage_binding_consumer_scopes
                     (storage_binding_id, consumer_scope_key, grant_generation, grant_kind,
                      state, granted_by, granted_at, resource_version)
                     SELECT id, ?1, 1, 'instance_default', 'active',
                            'system:org-create', ?2, 1
                     FROM storage_bindings WHERE is_instance_default = 1",
                    vals![consumer_scope_key, now],
                )
                .unchecked(),
                Statement::new(
                    "INSERT INTO consumer_scope_grant_events
                     (event_id, resource_kind, resource_stable_id, resource_generation_key,
                      consumer_scope_key, grant_generation, transition, previous_state,
                      resulting_state, actor_id, occurred_at, request_id)
                     VALUES (?1, 'network_boundary', 'instance:public', 0, ?2, 1,
                       'granted', NULL, 'active', 'system:org-create', ?3, ?4)",
                    vals![
                        event_id,
                        consumer_scope_key,
                        now,
                        format!("org-create:{slug}")
                    ],
                )
                .expecting(1),
            ])
            .await?;
        Ok(org_id)
    }

    /// Creates an organization attributed to an immutable control plan.
