    /// Set a change-set's lifecycle status, optionally stamping
    /// `applied_at` and/or `reverted_by_change_id`.
    ///
    /// Pass `applied_at = Some(t)` when transitioning to `applied`, and
    /// `reverted_by = Some(id)` when marking a change-set reverted by
    /// another. `None` arguments leave the corresponding columns untouched.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn set_changeset_status(
        &self,
        change_id: &str,
        status: &str,
        applied_at: Option<i64>,
        reverted_by: Option<&str>,
    ) -> Result<()> {
        self.backend
            .execute(
                "UPDATE change_requests
             SET status = ?2,
                 applied_at = COALESCE(?3, applied_at),
                 reverted_by_change_id = COALESCE(?4, reverted_by_change_id)
             WHERE change_id = ?1",
                &vals![change_id, status, applied_at, reverted_by],
            )
            .await?;
        Ok(())
    }

    /// Mark a git-backed change request applied, linking the promoting commit.
    ///
    /// Called by the indexer when it re-walks a registry surface and finds the
    /// verified HEAD commit carries an `AOS-Change-Id: <change_id>` trailer
    /// matching a `draft` change request (RFC-0004 "Configuration management",
    /// cross-referencing): the maintainer's `apr change merge` re-signed and
    /// pushed the draft, so the change request is now live. Stamps
    /// `status = 'applied'`, `applied_at = now`, and rewrites `git_commit` to
    /// the *promoting* (roster-signed) commit oid — the draft commit is
    /// superseded. Idempotent: re-marking an already-applied row is a harmless
    /// no-op on a status-guarded `UPDATE`.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn mark_changeset_applied_commit(
        &self,
        change_id: &str,
        commit_oid: &str,
    ) -> Result<()> {
        self.backend
            .execute(
                "UPDATE change_requests
             SET status = 'applied', applied_at = ?2, git_commit = ?3
             WHERE change_id = ?1 AND status = 'draft'",
                &vals![change_id, unix_now(), commit_oid],
            )
            .await?;
        Ok(())
    }

    /// Whether an audit row already records `result_commit`.
    ///
    /// The indexer synthesizes one `external` audit entry per out-of-band
    /// (direct-publish) commit it observes; this check keeps that synthesis
    /// idempotent across re-indexes, so the same commit is never audited twice
    /// (RFC-0004 "Configuration management", cross-referencing).
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn audit_exists_for_commit(&self, action: &str, result_commit: &str) -> Result<bool> {
        Ok(self
            .backend
            .query_opt(
                "SELECT 1 FROM audit_log WHERE action = ?1 AND result_commit = ?2 LIMIT 1",
                &vals![action, result_commit],
            )
            .await?
            .is_some())
    }

    /// Apply a change-set atomically: run `apply_fn` for each revision in
    /// `seq` order inside one transaction, then stamp `status = 'applied'`
    /// and `applied_at = now`.
    ///
    /// The caller supplies `apply_fn`, the live-object mutation for one
    /// revision (e.g. setting a registry's visibility). If any invocation
    /// fails the whole transaction rolls back and neither the live objects
    /// nor the changeset status change. The closure is `FnMut` so callers
    /// may thread mutable state through it.
    ///
    /// Note that `apply_fn` mutates live objects through a *separate*
    /// connection (it receives only the [`RevisionRow`], not the
    /// transaction), so its writes are not rolled back by a later revision's
    /// failure; the engine stages revisions only for changes whose live
    /// writes are individually idempotent and re-appliable (visibility,
    /// membership grants/revokes), so a partial apply is recoverable by
    /// re-applying.
    ///
    /// # Errors
    ///
    /// Returns an error if loading the revisions fails, if any `apply_fn`
    /// call returns an error, or on database failure committing the
    /// transaction.
    pub async fn apply_changeset<F>(&self, change_id: &str, mut apply_fn: F) -> Result<()>
    where
        F: for<'r> FnMut(
            &'r RevisionRow,
        )
            -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<()>> + 'r>>,
    {
        let revisions = self.list_revisions(change_id).await?;
        for revision in &revisions {
            apply_fn(revision).await?;
        }
        self.mark_changeset_applied(change_id).await?;
        Ok(())
    }

    /// Stamps a change-set `applied`, recording the current time.
    ///
    /// This is the single status write that follows a change-set's
    /// per-revision live mutations; it is atomic on its own, so no transaction
    /// is needed.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn mark_changeset_applied(&self, change_id: &str) -> Result<()> {
        self.backend
            .execute(
                "UPDATE change_requests SET status = 'applied', applied_at = ?2
             WHERE change_id = ?1",
                &vals![change_id, unix_now()],
            )
            .await?;
        Ok(())
    }

    /// List change-sets at or below `scope`, newest first.
    ///
    /// Uses the same stable-scope ancestor graph as [`Database::list_audit`]:
    /// a query at an org scope surfaces change-sets targeting its registries.
    /// The `instance` scope lists every live-scope change-set.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_changesets(&self, scope: &str) -> Result<Vec<ChangesetRow>> {
        let rows = self
            .backend
            .query(
                &format!(
                    "SELECT {CHANGESET_COLUMNS} FROM change_requests \
                 ORDER BY created_at DESC, change_id DESC"
                ),
                &[],
            )
            .await?;
        let mut out = Vec::new();
        for row in &rows {
            let changeset = row_to_changeset(row)?;
            let covered = self
                .backend
                .query_opt(
                    "SELECT 1 FROM authorization_scope_ancestors
                      WHERE descendant_scope_key = ?1 AND ancestor_scope_key = ?2",
                    &vals![changeset.scope, scope],
                )
                .await?
                .is_some();
            if covered {
                out.push(changeset);
            }
        }
        Ok(out)
    }

    // -- webhooks -----------------------------------------------------------

    /// Seeds a webhook subscription for a debug-build fixture.
    ///
    /// `events` is the set of event-type strings the hook subscribes to (an
    /// empty slice subscribes to *all* events). `secret_version_ref` is an
    /// opaque test-provider reference, never plaintext signing material.
    ///
    /// `url` is validated against the SSRF guard
    /// ([`crate::url_guard::is_safe_remote_url`]) — the delivery worker `POST`s to
    /// it from inside the hub network, so a loopback/link-local/private or
    /// non-`http(s)` target is rejected here, just as mirror upstreams are.
    ///
    /// # Errors
    ///
    /// Returns an error when `url` fails the SSRF guard, or on database
    /// failure.
    #[cfg(any(test, debug_assertions, feature = "do-e2e-test-support"))]
    pub async fn seed_webhook_for_test(
        &self,
        org_id: i64,
        url: &str,
        secret_version_ref: &str,
        credential_fingerprint: &str,
        events: &[String],
    ) -> Result<i64> {
        crate::url_guard::is_safe_remote_url(url).context("rejecting webhook URL")?;
        crate::secret_version::validate_secret_version_ref(secret_version_ref)?;
        anyhow::ensure!(
            credential_fingerprint.len() == 64
                && credential_fingerprint
                    .bytes()
                    .all(|byte| byte.is_ascii_hexdigit()),
            "webhook credential fingerprint must be SHA-256 hex"
        );
        self.backend
            .execute_insert(
                "INSERT INTO webhooks
                 (org_id, url, secret_version_ref, credential_fingerprint, events,
                  active, created_at)
                 VALUES (?1, ?2, ?3, ?4, ?5, 1, ?6)",
                &vals![
                    org_id,
                    url,
                    secret_version_ref,
                    credential_fingerprint,
                    serde_json::to_string(events)?,
                    unix_now()
                ],
            )
            .await
    }

    /// Creates one webhook through an actor-attributed control plan.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsafe URL, missing organization, duplicate
    /// plan, serialization failure, or checked transaction failure.
    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn create_webhook_from_plan(
        &self,
        org_id: i64,
        url: &str,
        secret_version_ref: &str,
        credential_fingerprint: &str,
        events: &[String],
        plan_id: &str,
        actor_kind: &str,
        actor_id: Option<i64>,
        actor_label: &str,
    ) -> Result<i64> {
        crate::url_guard::is_safe_remote_url(url).context("rejecting webhook URL")?;
        crate::secret_version::validate_secret_version_ref(secret_version_ref)?;
        anyhow::ensure!(
            credential_fingerprint.len() == 64
                && credential_fingerprint
                    .bytes()
                    .all(|byte| byte.is_ascii_hexdigit()),
            "webhook credential fingerprint must be SHA-256 hex"
        );
        let webhook_count = self
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM webhooks WHERE org_id = ?1",
                &vals![org_id],
            )
            .await?
            .context("webhook count query returned no row")?
            .get::<i64>(0)?;
        anyhow::ensure!(
            webhook_count < MAX_WEBHOOKS_PER_ORG as i64,
            "organization webhook limit reached"
        );
        let org_scope: String = self
            .backend
            .query_opt(
                "SELECT stable_id FROM orgs WHERE id = ?1 AND deleted_at IS NULL",
                &vals![org_id],
            )
            .await?
            .context("webhook owner organization does not exist")?
            .get(0)?;
        let id = portable_relational_id(uuid::Uuid::new_v4());
        let now = unix_now();
        let stable_id = format!("webhook:{id}");
        let event_id = uuid::Uuid::new_v4().simple().to_string();
        let new_json = serde_json::to_string(&serde_json::json!({
            "id": id,
            "url": url,
            "events": events,
            "secretVersionRef": secret_version_ref,
            "credentialFingerprint": credential_fingerprint,
            "active": true,
            "resourceVersion": 1,
        }))?;
        let payload_json = serde_json::to_string(&serde_json::json!({
            "changeId": plan_id,
            "webhookId": id,
            "resourceVersion": 1,
        }))?;
        self.backend
            .checked_batch(&[
                // Serialize the per-org cardinality guard on every SQL backend.
                // The update deliberately preserves the resource version: it is
                // an internal lock, not a user-visible organization mutation.
                Statement::new(
                    "UPDATE orgs SET updated_at = updated_at
                      WHERE id = ?1 AND deleted_at IS NULL",
                    vals![org_id],
                )
                .unchecked(),
                Statement::new(
                    format!(
                        "INSERT INTO webhooks
                         (id, org_id, url, secret_version_ref, credential_fingerprint,
                          events, active, created_at, updated_at, creation_plan_id)
                         SELECT ?1, ?2, ?3, ?4, ?5, ?6, 1, ?7, ?7, ?8
                          WHERE (SELECT COUNT(*) FROM webhooks WHERE org_id = ?2) < {}",
                        MAX_WEBHOOKS_PER_ORG
                    ),
                    vals![
                        id,
                        org_id,
                        url,
                        secret_version_ref,
                        credential_fingerprint,
                        serde_json::to_string(events)?,
                        now,
                        plan_id
                    ],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO change_requests
                     (change_id, actor_kind, actor_id, actor_label, scope, status,
                      summary, created_at, applied_at)
                     VALUES (?1, ?2, ?3, ?4, ?5, 'applied', ?6, ?7, ?7)",
                    vals![
                        plan_id,
                        actor_kind,
                        actor_id,
                        sanitize_log_text(actor_label),
                        org_scope,
                        format!("create webhook subscription {id}"),
                        now
                    ],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO change_request_revisions
                     (change_id, object_type, object_id, op, old_json, new_json, seq)
                     VALUES (?1, 'webhook', ?2, 'create', NULL, ?3, 0)",
                    vals![plan_id, stable_id, new_json],
                )
                .expecting(1),
                Statement::new(
                    "INSERT INTO audit_log
                     (outbox_event_id, change_id, actor_kind, actor_id, actor_label,
                      action, scope, detail, created_at)
                     VALUES (?1, ?2, ?3, ?4, ?5, 'webhook.created', ?6, ?7, ?8)",
                    vals![
                        event_id,
                        plan_id,
                        actor_kind,
                        actor_id,
                        sanitize_log_text(actor_label),
                        org_scope,
                        payload_json,
                        now
                    ],
                )
                .expecting(1),
                Self::topology_event_statement(&NewTopologyEvent {
                    event_id: &event_id,
                    event_name: "webhook.created",
                    owner_scope_key: &org_scope,
                    resource_kind: "webhook",
                    resource_stable_id: &stable_id,
                    resource_generation_key: 1,
                    actor_kind,
                    actor_id,
                    actor_label,
                    payload_json: &payload_json,
                    occurred_at: now,
                }),
            ])
            .await?;
        Ok(id)
    }

    /// List an org's webhook subscriptions, oldest first.
    ///
    /// # Errors
    ///
    /// Returns an error on database failure.
    pub async fn list_webhooks(&self, org_id: i64) -> Result<Vec<WebhookRecord>> {
        let rows = self
            .backend
            .query(
                "SELECT id, org_id, url, secret_version_ref, credential_fingerprint,
                        events, active, created_at, resource_version, updated_at
             FROM webhooks WHERE org_id = ?1 ORDER BY id",
                &vals![org_id],
            )
            .await?;
        rows.iter().map(row_to_webhook).collect()
    }

