    #[test]
    fn storage_binding_read_sql_projects_only_non_sensitive_columns() {
        fn projected_columns(sql: &str) -> Vec<&str> {
            sql.split_once("FROM")
                .unwrap()
                .0
                .strip_prefix("SELECT")
                .unwrap()
                .split(',')
                .map(str::trim)
                .collect::<Vec<_>>()
        }
        assert_eq!(
            projected_columns(STORAGE_BINDING_READ_DETAIL_SQL),
            [
                "id",
                "org_id",
                "name",
                "kind",
                "is_instance_default",
                "stable_id",
                "owner_scope_key",
                "resource_version",
                "created_at",
                "updated_at",
            ],
        );
        assert_eq!(
            projected_columns(STORAGE_BINDING_READ_SUMMARY_SQL),
            [
                "id",
                "org_id",
                "name",
                "kind",
                "is_instance_default",
                "stable_id",
            ],
        );
        for sql in [
            STORAGE_BINDING_READ_DETAIL_SQL,
            STORAGE_BINDING_READ_SUMMARY_SQL,
        ] {
            for forbidden in [
                "local_root_path",
                "object_bucket",
                "object_prefix",
                "endpoint_scheme",
                "endpoint_host_kind",
                "endpoint_host_bytes",
                "endpoint_port",
                "signing_region",
                "access_mode",
                "secret_version_ref",
                "credential_fingerprint",
            ] {
                assert!(
                    !sql.contains(forbidden),
                    "read projection selected {forbidden}"
                );
            }
        }
    }

