    fn signed_image_package() -> aos_registry_surface::manifest::PackageToml {
        use aos_registry_surface::manifest::{
            immutable_image_info_object_key, immutable_image_object_key, ImageCompression,
            ImageDelivery, ImageInfoReference, ImageTarget, ImageUkiIdentity,
            ImageVerificationState,
        };

        #[derive(serde::Serialize)]
        struct DeliveryWrapper<'a> {
            delivery: &'a ImageDelivery,
        }

        let delivery = |format: &str| {
            let (sha256, extension, media_type, compatible_targets, info_sha256) = match format {
                "raw" => (
                    "a".repeat(64),
                    "img",
                    "application/vnd.aos.disk-image.raw",
                    vec![ImageTarget::BareMetal],
                    "c".repeat(64),
                ),
                "qcow2" => (
                    "b".repeat(64),
                    "qcow2",
                    "application/vnd.aos.disk-image.qcow2",
                    vec![ImageTarget::QemuKvm, ImageTarget::Openstack],
                    "d".repeat(64),
                ),
                other => panic!("unsupported image test format {other}"),
            };
            let filename = format!("aos-system.{extension}");
            ImageDelivery {
                schema_version: 1,
                release: "2026.8.0".into(),
                platform: "x86_64-linux".into(),
                architecture: "x86_64".into(),
                logical_image_id: "e".repeat(64),
                logical_disk_sha256: "a".repeat(64),
                rootfs_sha256: "f".repeat(64),
                filename: filename.clone(),
                object_key: immutable_image_object_key(&sha256, &filename),
                media_type: media_type.into(),
                compression: ImageCompression::None,
                byte_size: 4096,
                sha256: sha256.clone(),
                compatible_targets,
                uki: ImageUkiIdentity {
                    filename: "aos-system.efi".into(),
                    esp_path: "EFI/Linux/aos-system.efi".into(),
                    byte_size: 1024,
                    sha256: "1".repeat(64),
                    verification: ImageVerificationState::Unsigned,
                    signer_cert_sha256: None,
                    sbat: Vec::new(),
                    measured: false,
                    expected_pcr11: None,
                },
                image_info: ImageInfoReference {
                    filename: "image-info.json".into(),
                    object_key: immutable_image_info_object_key(&sha256, &info_sha256),
                    media_type: "application/vnd.aos.image-info+json".into(),
                    byte_size: 512,
                    sha256: info_sha256,
                },
            }
        };
        let mut images = String::new();
        for format in ["raw", "qcow2"] {
            let delivery = delivery(format);
            let store_hash = if format == "raw" {
                "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            } else {
                "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
            };
            let encoded = toml::to_string(&DeliveryWrapper {
                delivery: &delivery,
            })
            .unwrap()
            .replace(
                "[delivery]",
                "[versions.platforms.x86_64-linux.images.delivery]",
            )
            .replace(
                "[delivery.uki]",
                "[versions.platforms.x86_64-linux.images.delivery.uki]",
            )
            .replace(
                "[delivery.image_info]",
                "[versions.platforms.x86_64-linux.images.delivery.image_info]",
            );
            images.push_str(&format!(
                r#"
[[versions.platforms.x86_64-linux.images]]
format = "{format}"
store_path = "/aos/store/{store_hash}-aos-system-{format}"
nar_hash = "sha256:nar"
nar_size = 1
{encoded}
"#,
            ));
        }
        toml::from_str(&format!(
            r#"
[package]
name = "aos-system"
description = "AOS system"
license = "MIT"
maintainer = "aos"
sysroot = true

[[versions]]
version = "2026.8.0"

[versions.platforms.x86_64-linux]
store_path = "/aos/store/aos-system"
closure_size = 1
source_drv = ""
source_nar_hash = ""
{images}
"#,
        ))
        .unwrap()
    }

    fn signed_image_release_snapshot(
        package: &aos_registry_surface::manifest::PackageToml,
        release: &str,
        commit: &str,
        tag_oid: &str,
    ) -> ReleaseImageSnapshot {
        let mut images = Vec::new();
        for version in &package.versions {
            if version.version != release {
                continue;
            }
            for (platform, artifact) in &version.platforms {
                for image in &artifact.images {
                    images.push(IndexedSystemImage {
                        package: package.package.name.clone(),
                        release: release.to_string(),
                        platform: platform.clone(),
                        format: image.format.clone(),
                        delivery: image.delivery.clone(),
                    });
                }
            }
        }
        ReleaseImageSnapshot {
            release_tag: release.to_string(),
            source_commit: commit.to_string(),
            verified_tag_oid: tag_oid.to_string(),
            catalog_digest: "d".repeat(64),
            images,
        }
    }

    #[tokio::test]
    async fn webhook_limit_is_serialized_inside_the_create_transaction() {
        let db = Arc::new(Database::open_in_memory().await.unwrap());
        let org_id = db.create_org("webhook-cap", "Webhook Cap").await.unwrap();
        let fingerprint = "0".repeat(64);
        for ordinal in 0..(MAX_WEBHOOKS_PER_ORG - 1) {
            db.create_webhook_from_plan(
                org_id,
                "https://hooks.example.test/aos",
                "native://webhook-cap/signing/v1",
                &fingerprint,
                &[],
                &format!("cap-seed-{ordinal}"),
                "system",
                None,
                "webhook limit test",
            )
            .await
            .unwrap();
        }

        let fingerprint = fingerprint.as_str();
        let create = |plan_id: &'static str| {
            let db = Arc::clone(&db);
            async move {
                db.create_webhook_from_plan(
                    org_id,
                    "https://hooks.example.test/aos",
                    "native://webhook-cap/signing/v1",
                    fingerprint,
                    &[],
                    plan_id,
                    "system",
                    None,
                    "webhook limit test",
                )
                .await
            }
        };
        let (left, right) = tokio::join!(create("cap-race-left"), create("cap-race-right"));
        assert_ne!(
            left.is_ok(),
            right.is_ok(),
            "exactly one contender wins the last slot"
        );
        assert_eq!(
            db.list_webhooks(org_id).await.unwrap().len(),
            MAX_WEBHOOKS_PER_ORG
        );
    }

    #[test]
    fn fresh_schema_is_final_and_foreign_key_clean() {
        assert!(!MIGRATIONS.is_empty(), "the schema has a baseline");
        let connection = Connection::open_in_memory().unwrap();
        connection
            .execute_batch("PRAGMA foreign_keys = ON;")
            .unwrap();
        for migration in MIGRATIONS {
            connection.execute_batch(migration).unwrap();
        }

        let identity: String = connection
            .query_row("SELECT identity FROM hub_schema_identity", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(identity, SCHEMA_IDENTITY);

        let violations: i64 = connection
            .query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(violations, 0, "fresh baseline violates a foreign key");

        let schema = MIGRATIONS[0];
        for forbidden in [
            "credential_ref",
            "CREATE TABLE frontends",
            "storage_bindings_instance_default_idx",
            " root TEXT",
            " access TEXT",
            " endpoint TEXT",
        ] {
            assert!(
                !schema.contains(forbidden),
                "final topology schema contains removed storage token {forbidden:?}"
            );
        }
        let removed_identity_columns: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('registries')
                 WHERE name IN ('source_url', 'storage_binding_id', 'prefix')",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(removed_identity_columns, 0);

        for table in [
            "binary_caches",
            "surface_placements",
            "surface_write_authorities",
            "domains",
            "network_boundaries",
            "delivery_endpoints",
            "storage_gateways",
            "delivery_routes",
            "delivery_route_configurations",
            "canonical_routes",
            "image_snapshots",
            "image_snapshot_references",
            "image_snapshot_leases",
        ] {
            let present: i64 = connection
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
                    [table],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(present, 1, "final table {table} is missing");
        }
        for table in ["caches", "frontends", "frontend_probes"] {
            let present: i64 = connection
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
                    [table],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(present, 0, "legacy table {table} survived the baseline");
        }

        let route_columns: Vec<String> = connection
            .prepare("PRAGMA table_info(delivery_routes)")
            .unwrap()
            .query_map([], |row| row.get(1))
            .unwrap()
            .collect::<rusqlite::Result<_>>()
            .unwrap();
        for required in [
            "id",
            "endpoint_id",
            "endpoint_generation",
            "consumer_scope_key",
            "access_policy_digest",
            "placement_policy_revision_id",
        ] {
            assert!(
                route_columns.iter().any(|column| column == required),
                "final route column {required} is missing"
            );
        }
        for forbidden in ["domain_id", "placement_policy_id", "readiness_state"] {
            assert!(
                route_columns.iter().all(|column| column != forbidden),
                "legacy route column {forbidden} survived the baseline"
            );
        }

        let public_boundary: (i64, String) = connection
            .query_row(
                "SELECT d.revision, d.state
                 FROM network_boundary_defaults d
                 WHERE d.boundary_id = 'instance:public'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(public_boundary, (1, "active".to_string()));
    }

    #[tokio::test]
    async fn migrate_register_and_reopen() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("hub.db");
        {
            let db = Database::open(&path).await.unwrap();
            db.register_registry("demo", &["k".into()], true)
                .await
                .unwrap();
        }
        let db = Database::open(&path).await.unwrap();
        let reg = db.registry_by_slug("demo").await.unwrap().unwrap();
        assert_eq!(reg.trust_keys, vec!["k".to_string()]);
        assert!(reg.require_signatures);
        assert_eq!(
            db.index_status(reg.id).await.unwrap().unwrap().state,
            "empty"
        );
    }

    #[tokio::test]
    async fn migrate_refuses_pre_cutover_version_collision() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("legacy.db");
        let connection = Connection::open(&path).unwrap();
        connection
            .execute_batch(
                "CREATE TABLE schema_version(version INTEGER NOT NULL);
                 INSERT INTO schema_version(version) VALUES (1);
                 CREATE TABLE registries(id INTEGER PRIMARY KEY, slug TEXT NOT NULL);",
            )
            .unwrap();
        drop(connection);

        let error = match Database::open(&path).await {
            Ok(_) => panic!("pre-cutover schema must be refused"),
            Err(error) => error,
        };
        let message = format!("{error:#}");
        assert!(
            message.contains("predates the topology hard cutover"),
            "{message}"
        );
    }

    #[tokio::test]
    async fn snapshot_replace_is_idempotent() {
        let db = Database::open_in_memory().await.unwrap();
        let id = db.register_registry("demo", &[], false).await.unwrap();
        let package: aos_registry_surface::manifest::PackageToml = toml::from_str(
            r#"
            [package]
            name = "curl"
            description = "URL transfers"
            license = "MIT"
            maintainer = "aos"
            [[versions]]
            version = "8.5.0"
            [versions.platforms.x86_64-linux]
            store_path = "/var/lib/store/abc-curl-8.5.0"
            nar_hash = "sha256:aa"
            nar_size = 10
            closure_size = 20
            source_drv = "/var/lib/store/abc.drv"
            source_nar_hash = "sha256:bb"
            "#,
        )
        .unwrap();
        let release_snapshot_artifacts = vec![ReleaseSnapshotArtifact {
            package_name: "curl".into(),
            package_version: "8.5.0".into(),
            platform: "x86_64-linux".into(),
            artifact_kind: "output".into(),
            store_path: "/nix/store/abc-curl".into(),
            store_hash: "abc".into(),
        }];
        let release_manifest_digest = hex::encode(sha2::Sha256::digest(
            serde_json::to_vec(&release_snapshot_artifacts).unwrap(),
        ));
        let mut snapshot = IndexSnapshot {
            commit: "c".repeat(64),
            name: "demo".into(),
            description: None,
            readme: None,
            caches: vec![("https://cache.example".into(), 40)],
            roster: vec![("alice".into(), "demo:Ed25519:AA".into(), "active".into())],
            packages: vec![package],
            releases: vec![ReleaseRow {
                semver: "1.0.0".into(),
                tag_oid: "a".repeat(64),
                commit_oid: "c".repeat(64),
                signer: None,
                tagged_at: Some(1),
                pack_present: true,
            }],
            release_artifact_snapshots: vec![ReleaseArtifactSnapshot {
                release_tag: "1.0.0".into(),
                source_commit: "c".repeat(64),
                verified_tag_oid: "a".repeat(64),
                manifest_digest: release_manifest_digest,
                artifacts: release_snapshot_artifacts,
            }],
            release_images: Vec::new(),
            channels: vec![ChannelSummary {
                name: "stable".into(),
                frontier: Some("1.0.0".into()),
                partitions: vec![Some("1.0.0".into()); 256],
            }],
            refs_digest: Some("d".repeat(64)),
            cache_stack: None,
        };
        db.apply_snapshot(id, &snapshot).await.unwrap();
        let retention_releases = db.list_retention_release_snapshots(id).await.unwrap();
        assert_eq!(retention_releases.len(), 1);
        assert_eq!(retention_releases[0].artifacts[0].store_hash, "abc");
        let release_id: i64 = db
            .backend
            .query_opt(
                "SELECT id FROM releases WHERE registry_id = ?1 AND semver = '1.0.0'",
                &vals![id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        db.apply_snapshot(id, &snapshot).await.unwrap();
        let stable_release_id: i64 = db
            .backend
            .query_opt(
                "SELECT id FROM releases WHERE registry_id = ?1 AND semver = '1.0.0'",
                &vals![id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(stable_release_id, release_id);
        let artifact_count: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM release_artifacts WHERE release_id = ?1",
                &vals![release_id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(artifact_count, 1);

        let channel_id: i64 = db
            .backend
            .query_opt(
                "SELECT id FROM channels WHERE registry_id = ?1 AND name = 'stable'",
                &vals![id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        let channels = std::mem::take(&mut snapshot.channels);
        db.apply_snapshot(id, &snapshot).await.unwrap();
        assert!(db.list_channels(id).await.unwrap().is_empty());
        snapshot.channels = channels;
        db.apply_snapshot(id, &snapshot).await.unwrap();
        let restored_channel_id: i64 = db
            .backend
            .query_opt(
                "SELECT id FROM channels WHERE registry_id = ?1 AND name = 'stable'",
                &vals![id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(restored_channel_id, channel_id);
        let mut refreshed_channels = snapshot.channels.clone();
        refreshed_channels[0].partitions[0] = None;
        let before_incremental = db.index_status(id).await.unwrap().unwrap();
        db.update_channels(id, &refreshed_channels).await.unwrap();
        let after_incremental = db.index_status(id).await.unwrap().unwrap();
        assert_eq!(
            after_incremental.generation,
            before_incremental.generation + 1
        );
        assert_ne!(
            after_incremental.content_digest,
            before_incremental.content_digest
        );
        db.update_channels(id, &refreshed_channels).await.unwrap();
        assert_eq!(
            db.list_channels(id).await.unwrap()[0]
                .partitions
                .iter()
                .flatten()
                .count(),
            255
        );
        db.apply_snapshot(id, &snapshot).await.unwrap();

        snapshot.releases[0].tag_oid = "force-retag".repeat(8);
        snapshot.releases[0].commit_oid = "changed-commit".repeat(8);
        assert!(db.apply_snapshot(id, &snapshot).await.is_err());
        let unchanged_release = db
            .backend
            .query_opt(
                "SELECT id, tag_oid, commit_oid FROM releases
                 WHERE registry_id = ?1 AND semver = '1.0.0'",
                &vals![id],
            )
            .await
            .unwrap()
            .unwrap();
        assert_eq!(unchanged_release.get::<i64>(0).unwrap(), release_id);
        assert_eq!(unchanged_release.get::<String>(1).unwrap(), "a".repeat(64));
        assert_eq!(unchanged_release.get::<String>(2).unwrap(), "c".repeat(64));
        let artifact_count_after_retag: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM release_artifacts WHERE release_id = ?1",
                &vals![release_id],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(artifact_count_after_retag, 1);

        let packages = db.list_packages(id).await.unwrap();
        assert_eq!(packages.len(), 1);
        assert_eq!(packages[0].latest_version.as_deref(), Some("8.5.0"));
        let detail = db.package_detail(id, "curl").await.unwrap().unwrap();
        assert_eq!(detail.versions[0].platforms[0].platform, "x86_64-linux");
        let channels = db.list_channels(id).await.unwrap();
        assert_eq!(channels[0].partitions.iter().flatten().count(), 256);
        assert_eq!(db.index_status(id).await.unwrap().unwrap().state, "fresh");
        assert_eq!(
            db.registry_cache_stack_entries(id)
                .await
                .unwrap()
                .first()
                .unwrap()
                .resolved_priority,
            40
        );
        assert!(db.list_releases(id).await.unwrap()[0].pack_present);
        assert_eq!(
            db.refs_digest(id).await.unwrap().as_deref(),
            Some(&*"d".repeat(64))
        );
        assert_eq!(
            db.all_store_hashes(id).await.unwrap(),
            vec!["abc".to_string()]
        );
    }

    #[tokio::test]
    async fn signed_images_require_complete_exact_placement_presence_and_remain_gc_roots() {
        let db = Database::open_in_memory().await.unwrap();
        let org_id = db.create_org("image-roots", "Image roots").await.unwrap();
        let registry_id = db
            .create_managed_registry(org_id, "", "system", "public", &[], false)
            .await
            .unwrap();
        let binding_id = create_test_binding(&db, org_id, "images", "/tmp/image-roots").await;
        let mut placement =
            topology_placement(SurfaceTarget::Registry(registry_id), "primary", "system", 0);
        placement.storage_binding_id = binding_id;
        let placement = db.create_surface_placement(&placement).await.unwrap();
        let placement = db
            .observe_surface_placement(placement.id, "ready", "complete", 1)
            .await
            .unwrap();

        let package = signed_image_package();
        let mut snapshot = IndexSnapshot {
            commit: "c".repeat(64),
            name: "AOS system".into(),
            packages: vec![package.clone()],
            releases: vec![ReleaseRow {
                semver: "2026.8.0".into(),
                tag_oid: "a".repeat(64),
                commit_oid: "c".repeat(64),
                signer: Some("release-signer".into()),
                tagged_at: Some(1),
                pack_present: true,
            }],
            release_images: vec![signed_image_release_snapshot(
                &package,
                "2026.8.0",
                &"c".repeat(64),
                &"a".repeat(64),
            )],
            channels: vec![ChannelSummary {
                name: "stable".into(),
                frontier: Some("2026.8.0".into()),
                partitions: vec![Some("2026.8.0".into()); 256],
            }],
            ..Default::default()
        };
        let identities = snapshot
            .release_images
            .iter()
            .flat_map(|release| &release.images)
            .flat_map(|image| {
                let disk = &image.delivery;
                [
                    VerifiedRegistryImageObject {
                        object_key: disk.object_key.clone(),
                        sha256: disk.sha256.clone(),
                        byte_size: i64::try_from(disk.byte_size).unwrap(),
                        strong_etag: format!("\"snapshot-sha256-{}\"", disk.sha256),
                    },
                    VerifiedRegistryImageObject {
                        object_key: disk.image_info.object_key.clone(),
                        sha256: disk.image_info.sha256.clone(),
                        byte_size: i64::try_from(disk.image_info.byte_size).unwrap(),
                        strong_etag: format!("\"snapshot-sha256-{}\"", disk.image_info.sha256),
                    },
                ]
            })
            .collect::<Vec<_>>();
        db.lease_image_snapshot(
            "in-flight-index",
            &identities[0].sha256,
            identities[0].byte_size,
            unix_now() + 60,
        )
        .await
        .unwrap();
        db.lease_image_snapshot(
            "peer-index",
            &identities[0].sha256,
            identities[0].byte_size,
            unix_now() + 60,
        )
        .await
        .unwrap();
        assert!(
            db.lease_image_snapshot(
                "conflicting-size",
                &identities[0].sha256,
                identities[0].byte_size + 1,
                unix_now() + 60,
            )
            .await
            .is_err(),
            "one digest must never acquire two byte-size identities"
        );
        assert!(
            db.collectible_image_snapshots(100)
                .await
                .unwrap()
                .is_empty(),
            "an in-flight verified response must be protected before roots commit"
        );
        assert!(
            db.apply_snapshot_with_image_presence(
                registry_id,
                &snapshot,
                placement.id,
                &identities[..1],
                unix_now(),
            )
            .await
            .is_err(),
            "incomplete presence must not commit the release or channel"
        );
        assert!(db.list_releases(registry_id).await.unwrap().is_empty());
        assert!(
            db.list_system_images(registry_id).await.unwrap().is_empty(),
            "partial disk/metadata publication must not become discoverable"
        );

        db.apply_snapshot_with_image_presence(
            registry_id,
            &snapshot,
            placement.id,
            &identities,
            unix_now(),
        )
        .await
        .unwrap();
        assert_eq!(
            db.channel_floor(registry_id, "stable")
                .await
                .unwrap()
                .as_deref(),
            Some("2026.8.0"),
            "channel visibility and its anti-rollback floor commit together"
        );
        let events_before_rollback: i64 = db
            .backend
            .query_opt("SELECT COUNT(*) FROM topology_event_outbox", &[])
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        let mut rollback = snapshot.clone();
        rollback.channels[0].frontier = Some("2026.7.0".into());
        rollback.channels[0].partitions = vec![Some("2026.7.0".into()); 256];
        assert!(
            db.apply_snapshot_with_image_presence(
                registry_id,
                &rollback,
                placement.id,
                &identities,
                unix_now(),
            )
            .await
            .is_err(),
            "a channel rollback must abort the complete snapshot transaction"
        );
        assert_eq!(
            db.list_channels(registry_id).await.unwrap()[0]
                .frontier
                .as_deref(),
            Some("2026.8.0"),
            "failed floor validation must not publish channel rows"
        );
        let events_after_rollback: i64 = db
            .backend
            .query_opt("SELECT COUNT(*) FROM topology_event_outbox", &[])
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(
            events_after_rollback, events_before_rollback,
            "failed floor validation must not publish index or release events"
        );
        assert!(
            db.release_image_snapshot_lease("in-flight-index")
                .await
                .unwrap(),
            "presence completion releases only its own lease"
        );
        assert!(
            db.release_image_snapshot_lease("peer-index").await.unwrap(),
            "committing one index must not delete a concurrent index lease"
        );
        let root_keys = db.list_system_image_root_keys(registry_id).await.unwrap();
        assert_eq!(
            root_keys.len(),
            4,
            "two encodings root disk and metadata bytes"
        );
        let mut replica_spec = topology_placement(
            SurfaceTarget::Registry(registry_id),
            "replica",
            "replica",
            10,
        );
        replica_spec.storage_binding_id = binding_id;
        let replica = db.create_surface_placement(&replica_spec).await.unwrap();
        let replica = db
            .observe_surface_placement(replica.id, "ready", "complete", 1)
            .await
            .unwrap();
        assert!(db
            .mark_index_empty_from_placement(registry_id, replica.id)
            .await
            .is_err());
        assert_eq!(
            db.index_status(registry_id).await.unwrap().unwrap().state,
            "fresh",
            "an empty replica must not clear authoritative discovery state"
        );
        db.record_registry_image_presence(registry_id, replica.id, &identities, unix_now())
            .await
            .unwrap();
        assert!(db
            .collectible_image_snapshots(100)
            .await
            .unwrap()
            .is_empty());
        let visible = db.list_system_images(registry_id).await.unwrap();
        assert_eq!(visible.len(), 2);
        let mut formats = visible
            .iter()
            .map(|image| image.format.as_str())
            .collect::<Vec<_>>();
        formats.sort_unstable();
        assert_eq!(formats, ["qcow2", "raw"]);

        let degraded = db
            .observe_surface_placement(placement.id, "degraded", "complete", 2)
            .await
            .unwrap();
        assert_eq!(
            db.list_system_images(registry_id).await.unwrap().len(),
            2,
            "canonical degraded complete placements remain readable"
        );
        let offline = db
            .update_surface_placement(
                degraded.id,
                &UpdateSurfacePlacementSpec {
                    expected_version: degraded.resource_version,
                    desired_state: "offline".into(),
                    desired_read_enabled: true,
                    read_order: degraded.read_order,
                },
            )
            .await
            .unwrap();
        assert!(
            db.list_system_images(registry_id).await.unwrap().len() == 2,
            "taking one placement offline must preserve a healthy verified replica"
        );
        db.update_surface_placement(
            offline.id,
            &UpdateSurfacePlacementSpec {
                expected_version: offline.resource_version,
                desired_state: "active".into(),
                desired_read_enabled: true,
                read_order: offline.read_order,
            },
        )
        .await
        .unwrap();
        assert_eq!(db.list_system_images(registry_id).await.unwrap().len(), 2);

        for key in root_keys {
            let object = db
                .surface_object_named(SurfaceTarget::Registry(registry_id), &key)
                .await
                .unwrap()
                .unwrap();
            assert!(
                !db.tombstone_surface_object(object.id, object.resource_version, unix_now())
                    .await
                    .unwrap(),
                "signed release root {key} must be protected from GC"
            );
        }
        snapshot.release_images.clear();
        db.apply_snapshot_with_image_presence(
            registry_id,
            &snapshot,
            placement.id,
            &[],
            unix_now(),
        )
        .await
        .unwrap();
        assert_eq!(
            db.collectible_image_snapshots(100).await.unwrap().len(),
            4,
            "removing signed roots reconciles stale references on every placement"
        );
        db.mark_index_empty_from_placement(registry_id, placement.id)
            .await
            .unwrap();
        let empty = db.index_status(registry_id).await.unwrap().unwrap();
        assert_eq!(empty.state, "empty");
        assert!(empty.error.is_none());
        assert!(empty.last_indexed_commit.is_none());
        assert!(empty.name.is_none());
        assert!(empty.description.is_none());
        assert!(empty.readme.is_none());
        assert!(db.refs_digest(registry_id).await.unwrap().is_none());
        assert!(db
            .registry_cache_stack(registry_id)
            .await
            .unwrap()
            .is_none());
        assert_eq!(db.collectible_image_snapshots(100).await.unwrap().len(), 4);
        assert!(db.list_packages(registry_id).await.unwrap().is_empty());
        assert!(db.list_releases(registry_id).await.unwrap().is_empty());
        assert!(db.list_channels(registry_id).await.unwrap().is_empty());
        assert!(db.list_roster(registry_id).await.unwrap().is_empty());
        assert!(db
            .registry_cache_stack_entries(registry_id)
            .await
            .unwrap()
            .is_empty());
        assert!(db
            .list_system_image_root_keys(registry_id)
            .await
            .unwrap()
            .is_empty());
        assert_eq!(
            db.channel_floor(registry_id, "stable")
                .await
                .unwrap()
                .as_deref(),
            Some("2026.8.0"),
            "emptying derived discovery must preserve system-of-record floors"
        );
    }

    #[tokio::test]
    async fn closure_resolution_resolves_refs_and_reverse_deps() {
        let db = Database::open_in_memory().await.unwrap();
        let id = db.register_registry("demo", &[], false).await.unwrap();
        // curl's closure references zlib (zzz) plus an out-of-registry hash
        // (qqq, e.g. a stdenv path); source_drv is recorded per the v19 column.
        let curl: aos_registry_surface::manifest::PackageToml = toml::from_str(
            r#"
            [package]
            name = "curl"
            description = "URL transfers"
            license = "MIT"
            maintainer = "aos"
            [[versions]]
            version = "8.5.0"
            [versions.platforms.x86_64-linux]
            store_path = "/var/lib/store/abc-curl-8.5.0"
            nar_hash = "sha256:aa"
            nar_size = 10
            closure_size = 20
            source_drv = "/var/lib/store/dabc-curl-8.5.0.drv"
            source_nar_hash = "sha256:bb"
            references = ["zzz", "qqq"]
            "#,
        )
        .unwrap();
        let zlib: aos_registry_surface::manifest::PackageToml = toml::from_str(
            r#"
            [package]
            name = "zlib"
            description = "compression"
            license = "Zlib"
            maintainer = "aos"
            [[versions]]
            version = "1.3.1"
            [versions.platforms.x86_64-linux]
            store_path = "/var/lib/store/zzz-zlib-1.3.1"
            nar_hash = "sha256:cc"
            nar_size = 5
            closure_size = 8
            source_drv = "/var/lib/store/dzzz-zlib-1.3.1.drv"
            source_nar_hash = "sha256:dd"
            references = []
            "#,
        )
        .unwrap();
        let snapshot = IndexSnapshot {
            commit: "c".repeat(64),
            name: "demo".into(),
            packages: vec![curl, zlib],
            ..Default::default()
        };
        db.apply_snapshot(id, &snapshot).await.unwrap();

        // The v19 source_drv column round-trips into PlatformDetail.
        let detail = db.package_detail(id, "curl").await.unwrap().unwrap();
        assert_eq!(
            detail.versions[0].platforms[0].source_drv,
            "/var/lib/store/dabc-curl-8.5.0.drv"
        );

        // resolve_reference_names: zzz resolves to zlib, qqq stays unresolved.
        let resolved = db
            .resolve_reference_names(id, &["zzz".to_string(), "qqq".to_string()])
            .await
            .unwrap();
        assert_eq!(
            resolved,
            vec![
                (
                    "zzz".to_string(),
                    Some("zlib".to_string()),
                    Some("1.3.1".to_string())
                ),
                ("qqq".to_string(), None, None),
            ]
        );

        // reverse_dependencies: curl requires zlib (zzz).
        let reverse = db.reverse_dependencies(id, "zzz").await.unwrap();
        assert_eq!(reverse, vec![("curl".to_string(), "8.5.0".to_string())]);
        // qqq is referenced by curl too (a second closure edge).
        assert_eq!(
            db.reverse_dependencies(id, "qqq").await.unwrap(),
            vec![("curl".to_string(), "8.5.0".to_string())]
        );
        // Nothing references a hash that appears in no closure.
        assert!(db
            .reverse_dependencies(id, "nope")
            .await
            .unwrap()
            .is_empty());

        // primary_store_hash prefers the named platform and falls back.
        assert_eq!(
            db.primary_store_hash(id, "zlib", "x86_64-linux")
                .await
                .unwrap(),
            Some("zzz".to_string())
        );
        assert_eq!(
            db.primary_store_hash(id, "zlib", "aarch64-linux")
                .await
                .unwrap(),
            Some("zzz".to_string()),
            "falls back to the first platform when the requested one is absent"
        );
        assert_eq!(
            db.primary_store_hash(id, "absent", "x86_64-linux")
                .await
                .unwrap(),
            None
        );

        // list_packages carries the latest version's closure size + platforms,
        // now via a single JOIN (no per-package N+1 sub-query).
        let packages = db.list_packages(id).await.unwrap();
        assert_eq!(packages.len(), 2, "both packages, name-ordered");
        assert_eq!(packages[0].name, "curl");
        let curl_row = packages.iter().find(|p| p.name == "curl").unwrap();
        assert_eq!(curl_row.closure_size, Some(20));
        assert_eq!(curl_row.platforms, vec!["x86_64-linux".to_string()]);

        // The capped browse listing returns the same rows under a high cap and
        // reports truncation when the cap is below the package count.
        let (uncapped, trunc) = db.list_packages_capped(id, 1000).await.unwrap();
        assert_eq!(uncapped.len(), 2);
        assert!(!trunc, "two packages are well under the cap");
        let (capped, trunc) = db.list_packages_capped(id, 1).await.unwrap();
        assert_eq!(capped.len(), 1, "cap limits the loaded set");
        assert_eq!(capped[0].name, "curl", "cap takes the name-ordered prefix");
        assert!(trunc, "a registry larger than the cap is flagged truncated");
    }

    #[tokio::test]
    async fn failure_marks_state_without_dropping_index() {
        let db = Database::open_in_memory().await.unwrap();
        let id = db.register_registry("demo", &[], false).await.unwrap();
        let snapshot = IndexSnapshot {
            commit: "c".repeat(64),
            name: "demo".into(),
            ..Default::default()
        };
        db.apply_snapshot(id, &snapshot).await.unwrap();
        db.mark_index_failed(id, "upstream unreachable")
            .await
            .unwrap();
        let status = db.index_status(id).await.unwrap().unwrap();
        assert_eq!(status.state, "failed");
        assert_eq!(status.error.as_deref(), Some("upstream unreachable"));
        // The last good index survives.
        assert_eq!(
            status.last_indexed_commit.as_deref(),
            Some(&*"c".repeat(64))
        );

        db.mark_index_stale(id, "connection refused").await.unwrap();
        let status = db.index_status(id).await.unwrap().unwrap();
        assert_eq!(status.state, "stale");
        assert_eq!(status.error.as_deref(), Some("connection refused"));
        assert_eq!(
            status.last_indexed_commit.as_deref(),
            Some(&*"c".repeat(64))
        );
    }

    #[tokio::test]
    async fn audit_and_changeset_scope_containment() {
        let db = Database::open_in_memory().await.unwrap();
        let acme_id = db.create_org("acme", "Acme").await.unwrap();
        let acme_scope = db.org_by_id(acme_id).await.unwrap().unwrap().stable_id;
        db.create_project(acme_id, "infra/prod", "Production")
            .await
            .unwrap();
        let project_scope = db.list_projects(acme_id).await.unwrap()[0]
            .scope_key
            .clone();
        let globex_id = db.create_org("globex", "Globex").await.unwrap();
        let globex_scope = db.org_by_id(globex_id).await.unwrap().unwrap().stable_id;
        db.record_audit(
            "system",
            None,
            "system",
            "a",
            &project_scope,
            None,
            None,
            None,
            None,
        )
        .await
        .unwrap();
        db.record_audit(
            "system",
            None,
            "system",
            "b",
            &globex_scope,
            None,
            None,
            None,
            None,
        )
        .await
        .unwrap();
        // An org-scoped query surfaces the registry-scoped row but not the
        // sibling org's.
        let rows = db.list_audit(&acme_scope).await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].action, "a");
        // The root scope lists everything, newest first.
        let all = db.list_audit("instance").await.unwrap();
        assert_eq!(all.len(), 2);
        assert_eq!(all[0].action, "b", "newest first");
    }

    #[test]
    fn sanitize_log_text_strips_c0_controls_but_keeps_tab() {
        // CR/LF and other C0 controls collapse to spaces; a tab is preserved.
        assert_eq!(sanitize_log_text("a\r\nb"), "a  b");
        assert_eq!(sanitize_log_text("x\tnice"), "x\tnice");
        assert_eq!(sanitize_log_text("ctrl\x07bell\x7fdel"), "ctrl bell del");
        assert_eq!(sanitize_log_text("clean/path-1.0"), "clean/path-1.0");
    }

    #[tokio::test]
    async fn record_audit_sanitizes_crlf_in_detail_and_label() {
        let db = Database::open_in_memory().await.unwrap();
        let org_id = db.create_org("acme", "Acme").await.unwrap();
        let org_scope = db.org_by_id(org_id).await.unwrap().unwrap().stable_id;
        // A forged label/detail with embedded CRLF must be stored sanitized so a
        // reader of the audit feed (or a log line derived from it) cannot be
        // fooled by an injected newline.
        db.record_audit(
            "token",
            None,
            "label\r\nINJECTED admin",
            "publish",
            &org_scope,
            None,
            None,
            None,
            Some("fetching http://host/x\r\nFAKE: line"),
        )
        .await
        .unwrap();
        let rows = db.list_audit(&org_scope).await.unwrap();
        assert_eq!(rows.len(), 1);
        assert!(
            !rows[0].actor_label.contains('\n') && !rows[0].actor_label.contains('\r'),
            "label retained CR/LF: {:?}",
            rows[0].actor_label
        );
        let detail = rows[0].detail.as_deref().unwrap_or("");
        assert!(
            !detail.contains('\n') && !detail.contains('\r'),
            "detail retained CR/LF: {detail:?}"
        );
        assert!(
            detail.contains("http://host/x"),
            "content preserved: {detail:?}"
        );
    }

    #[tokio::test]
    async fn draft_signing_key_is_generated_once_and_persists() {
        let db = Database::open_in_memory().await.unwrap();
        let sealer = crate::auth::seal::dev_sealer();
        let (key1, line1) = db
            .get_or_create_draft_signing_key(sealer.as_ref())
            .await
            .unwrap();
        // A second call returns the same key (persisted seed), not a fresh one.
        let (key2, line2) = db
            .get_or_create_draft_signing_key(sealer.as_ref())
            .await
            .unwrap();
        assert_eq!(key1.to_bytes(), key2.to_bytes());
        assert_eq!(line1, line2);
        assert!(line1.starts_with("aos-hub-draft:Ed25519:"));
        // The stored value is sealed, not the raw seed.
        let stored = db
            .instance_config_get("draft_signing_key")
            .await
            .unwrap()
            .unwrap();
        assert_ne!(stored, hex::encode(key1.to_bytes()));
    }

    #[tokio::test]
    async fn git_changeset_records_ref_and_commit() {
        let db = Database::open_in_memory().await.unwrap();
        db.create_git_changeset(
            "ch-1",
            "user",
            Some(7),
            "alice@acme.com",
            "instance",
            Some("edit registry.toml"),
            "refs/hub/changes/ch-1",
            "abc123",
            None,
            None,
        )
        .await
        .unwrap();
        let cs = db.changeset("ch-1").await.unwrap().unwrap();
        assert_eq!(cs.status, "draft");
        assert_eq!(cs.git_ref.as_deref(), Some("refs/hub/changes/ch-1"));
        assert_eq!(cs.git_commit.as_deref(), Some("abc123"));
        // A plain change-set leaves both columns NULL.
        db.create_changeset("ch-2", "user", Some(7), "alice@acme.com", "instance", None)
            .await
            .unwrap();
        let plain = db.changeset("ch-2").await.unwrap().unwrap();
        assert!(plain.git_ref.is_none());
        assert!(plain.git_commit.is_none());
    }

    #[tokio::test]
    async fn mark_changeset_applied_commit_links_promoting_commit() {
        let db = Database::open_in_memory().await.unwrap();
        db.create_git_changeset(
            "ch-3",
            "user",
            Some(7),
            "alice@acme.com",
            "instance",
            Some("edit"),
            "refs/hub/changes/ch-3",
            "draftoid",
            None,
            None,
        )
        .await
        .unwrap();
        db.mark_changeset_applied_commit("ch-3", "rosteroid")
            .await
            .unwrap();
        let cs = db.changeset("ch-3").await.unwrap().unwrap();
        assert_eq!(cs.status, "applied");
        assert!(cs.applied_at.is_some());
        assert_eq!(cs.git_commit.as_deref(), Some("rosteroid"));
        // Re-marking an applied row is a no-op (status-guarded UPDATE).
        db.mark_changeset_applied_commit("ch-3", "otheroid")
            .await
            .unwrap();
        let again = db.changeset("ch-3").await.unwrap().unwrap();
        assert_eq!(again.git_commit.as_deref(), Some("rosteroid"));
    }

    /// The central regression guard for the `closed_at`-axis design: closing and
    /// reopening a draft must leave `status = 'draft'`, so the indexer's
    /// `status='draft'`-guarded auto-merge still fires for a reopened change.
    #[tokio::test]
    async fn close_reopen_preserves_draft_auto_merge() {
        let db = Database::open_in_memory().await.unwrap();
        db.create_git_changeset(
            "ch-cr",
            "user",
            Some(1),
            "alice@acme.com",
            "instance",
            Some("edit"),
            "refs/hub/changes/ch-cr",
            "draftoid",
            Some("tighten caches"),
            Some("body text"),
        )
        .await
        .unwrap();
        // Title/body round-trip; opens un-closed.
        let cs = db.changeset("ch-cr").await.unwrap().unwrap();
        assert_eq!(cs.title.as_deref(), Some("tighten caches"));
        assert_eq!(cs.body.as_deref(), Some("body text"));
        assert!(cs.closed_at.is_none());

        // Close stamps closed_at but never touches status.
        db.close_changeset("ch-cr").await.unwrap();
        let cs = db.changeset("ch-cr").await.unwrap().unwrap();
        assert_eq!(cs.status, "draft");
        assert!(cs.closed_at.is_some());

        // Reopen clears closed_at.
        db.reopen_changeset("ch-cr").await.unwrap();
        let cs = db.changeset("ch-cr").await.unwrap().unwrap();
        assert!(cs.closed_at.is_none());

        // Auto-merge still flips the reopened draft to applied.
        db.mark_changeset_applied_commit("ch-cr", "rosteroid")
            .await
            .unwrap();
        let cs = db.changeset("ch-cr").await.unwrap().unwrap();
        assert_eq!(cs.status, "applied");
        assert_eq!(cs.git_commit.as_deref(), Some("rosteroid"));
    }

