    #[tokio::test]
    async fn purge_only_after_grace_window() {
        let db = Database::open_in_memory().await.unwrap();
        let org = db.create_org("acme", "Acme").await.unwrap();
        let original_scope = db.org_by_id(org).await.unwrap().unwrap().stable_id;
        let project_id = db.create_project(org, "infra", "Infra").await.unwrap();
        let project = db
            .list_projects(org)
            .await
            .unwrap()
            .into_iter()
            .find(|project| project.id == project_id)
            .unwrap();
        let original_project_scope = project.scope_key.clone();
        let user = db.create_user("member@example.test", None).await.unwrap();
        db.grant_membership("user", user, &original_scope, "viewer")
            .await
            .unwrap();
        db.grant_membership("user", user, &original_project_scope, "viewer")
            .await
            .unwrap();
        let (_, old_secret) = db
            .create_token(
                crate::domain::Principal::user(user),
                &original_project_scope,
                &[crate::domain::Permission::Read],
                None,
                None,
            )
            .await
            .unwrap();
        db.backend
            .execute(
                "INSERT INTO network_boundary_serving_pins
                 (pin_id, boundary_id, revision, consumer_scope_key, grant_generation,
                  grant_state, usage_kind, target_kind, target_stable_id,
                  target_generation_key, target_configuration_digest, acquired_by,
                  acquired_at, resource_version)
                 VALUES ('pin:purge-test', 'instance:public', 1, ?1, 1,
                   'active', 'topology_default', 'topology_default', ?1,
                   0, 'purge-test-digest', 'test', 0, 1)",
                &vals![original_scope],
            )
            .await
            .unwrap();
        db.backend
            .execute(
                "UPDATE network_boundary_revision_lifecycle
                 SET consumer_version = consumer_version + 1
                 WHERE boundary_id = 'instance:public' AND revision = 1",
                &[],
            )
            .await
            .unwrap();
        let now = unix_now();
        db.soft_delete_org(org, 100).await.unwrap();
        // Not yet purgeable just after deletion.
        assert!(db.list_purgeable_orgs(now).await.unwrap().is_empty());
        // Past the grace window it is listed and can be purged.
        let purgeable = db.list_purgeable_orgs(now + 200).await.unwrap();
        assert_eq!(purgeable.len(), 1);
        assert!(db.hard_purge_org(org, now + 200).await.unwrap());
        assert!(db
            .org_by_slug_including_deleted("acme")
            .await
            .unwrap()
            .is_none());
        let pin_count: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM network_boundary_serving_pins
                 WHERE consumer_scope_key = ?1",
                &vals![original_scope],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(pin_count, 0);
        let grant_count: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM network_boundary_consumer_scopes
                 WHERE boundary_id = 'instance:public'
                   AND consumer_scope_key = ?1",
                &vals![original_scope],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(grant_count, 0);
        let revoke_events: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM consumer_scope_grant_events
                 WHERE resource_stable_id = 'instance:public'
                   AND consumer_scope_key = ?1 AND transition = 'revoked'",
                &vals![original_scope],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(revoke_events, 1);
        assert!(db.validate_token(&old_secret).await.unwrap().is_none());
        assert!(db
            .list_memberships_for("user", user)
            .await
            .unwrap()
            .is_empty());
        let recreated = db.create_org("acme", "Acme Recreated").await.unwrap();
        let recreated_scope = db.org_by_id(recreated).await.unwrap().unwrap().stable_id;
        assert_ne!(original_scope, recreated_scope);
        let recreated_project_id = db
            .create_project(recreated, "infra", "Infra")
            .await
            .unwrap();
        let recreated_project_scope = db
            .list_projects(recreated)
            .await
            .unwrap()
            .into_iter()
            .find(|project| project.id == recreated_project_id)
            .unwrap()
            .scope_key;
        assert_ne!(original_project_scope, recreated_project_scope);
        let recreated_grant: i64 = db
            .backend
            .query_opt(
                "SELECT COUNT(*) FROM network_boundary_consumer_scopes
                 WHERE boundary_id = 'instance:public'
                   AND consumer_scope_key = ?1 AND state = 'active'",
                &vals![recreated_scope],
            )
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        assert_eq!(recreated_grant, 1);
    }

    #[tokio::test]
    async fn sibling_surface_scopes_are_isolated_and_slug_reuse_gets_new_identity() {
        let db = Database::open_in_memory().await.unwrap();
        let org_id = db.create_org("acme", "Acme").await.unwrap();
        db.create_project(org_id, "infra", "Infra").await.unwrap();
        let first_id = db
            .create_managed_registry(org_id, "infra", "packages", "private", &[], true)
            .await
            .unwrap();
        let sibling_id = db
            .create_managed_registry(org_id, "infra", "images", "private", &[], true)
            .await
            .unwrap();
        let first = db.registry_by_id(first_id).await.unwrap().unwrap();
        let sibling = db.registry_by_id(sibling_id).await.unwrap().unwrap();
        assert_eq!(first.owner_scope_key, sibling.owner_scope_key);
        assert_ne!(first.scope_key, sibling.scope_key);

        let user = db.create_user("reader@example.test", None).await.unwrap();
        db.grant_membership("user", user, &first.scope_key, "viewer")
            .await
            .unwrap();
        let grants = db
            .effective_scopes(crate::domain::Principal::user(user))
            .await
            .unwrap();
        let first_context = db
            .authorization_context(&first.scope_key)
            .await
            .unwrap()
            .unwrap();
        let sibling_context = db
            .authorization_context(&sibling.scope_key)
            .await
            .unwrap()
            .unwrap();
        assert!(crate::domain::iam::allow(
            &grants,
            crate::domain::Permission::Read,
            &first_context,
        ));
        assert!(!crate::domain::iam::allow(
            &grants,
            crate::domain::Permission::Read,
            &sibling_context,
        ));

        let old_scope = first.scope_key;
        assert!(db.seed_delete_registry_for_test(first_id).await.unwrap());
        let grants_after_delete = db
            .effective_scopes(crate::domain::Principal::user(user))
            .await
            .unwrap();
        assert!(grants_after_delete
            .iter()
            .all(|(scope, _)| scope.as_str() != old_scope));
        let replacement_id = db
            .create_managed_registry(org_id, "infra", "packages", "private", &[], true)
            .await
            .unwrap();
        let replacement = db.registry_by_id(replacement_id).await.unwrap().unwrap();
        assert_ne!(old_scope, replacement.scope_key);
        let replacement_context = db
            .authorization_context(&replacement.scope_key)
            .await
            .unwrap()
            .unwrap();
        assert!(!crate::domain::iam::allow(
            &grants_after_delete,
            crate::domain::Permission::Read,
            &replacement_context,
        ));
    }

    // regression: a restore landing between `list_purgeable_orgs` and
    // `hard_purge_org` (the unguarded list+delete race) must not destroy the
    // now-active org. `hard_purge_org` re-asserts the soft-deleted/past-grace
    // predicate, so the delete is a no-op once the org is restored.
    #[tokio::test]
    async fn purge_is_no_op_for_org_restored_in_window() {
        let db = Database::open_in_memory().await.unwrap();
        let org = db.create_org("acme", "Acme").await.unwrap();
        db.register_owned(org, "acme/cdn").await;
        // Soft-delete with a zero grace window so the org is purgeable now.
        db.soft_delete_org(org, 0).await.unwrap();
        let purgeable = db.list_purgeable_orgs(unix_now()).await.unwrap();
        assert_eq!(purgeable.len(), 1);

        // The admin restores it before the purge job reaches the delete.
        assert!(db.restore_org(org).await.unwrap());

        // The purge delete is now a no-op: it returns `Ok(false)` and the
        // org — and everything it owns — survives.
        assert!(!db.hard_purge_org(org, unix_now()).await.unwrap());
        assert!(db.org_by_slug("acme").await.unwrap().is_some());
        assert!(db.org_is_active(org).await.unwrap());
        assert_eq!(db.list_registries().await.unwrap().len(), 1);
    }

